import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ClipboardListIcon, SaveIcon, TrashIcon, CubeIcon, PlusIcon, ExclamationTriangleIcon } from '../assets/icons';
import type { CheckListPageProps, StockItem, StockMovement, PurchaseRequest } from '../types';
import Modal from '../components/Modal';

// Local Interface for Checklist Entries
interface CheckListEntry {
    id: string;
    project: string; // Nome do Cliente / Obra
    technicianCheckIn: string;
    dateCheckIn: string;
    status: 'open' | 'closed';
    itemsReserved: { itemId: string; quantity: number; name: string }[];

    // Checkout data
    dateCheckOut?: string;
    technicianCheckOut?: string;
    itemsUsed?: { itemId: string; quantity: number; name: string }[];
}

const CheckListPage: React.FC<CheckListPageProps> = ({ view }) => {
    const [checklists, setChecklists] = useState<CheckListEntry[]>([]);
    const [stockItems, setStockItems] = useState<StockItem[]>([]);

    // Forms State
    const [newCheckIn, setNewCheckIn] = useState<Partial<CheckListEntry>>({
        project: '',
        technicianCheckIn: '',
        dateCheckIn: new Date().toISOString().split('T')[0],
        itemsReserved: []
    });

    // Selection State for Checkout
    const [selectedChecklist, setSelectedChecklist] = useState<CheckListEntry | null>(null);
    const [checkoutData, setCheckoutData] = useState({
        dateCheckOut: new Date().toISOString().split('T')[0],
        technicianCheckOut: '',
        itemsUsed: [] as { itemId: string; quantity: number; name: string }[]
    });

    // Temporary state for adding items to CheckIn
    const [tempItem, setTempItem] = useState({ itemId: '', quantity: 1 });

    useEffect(() => {
        const savedChecklists = localStorage.getItem('checklist_entries');
        const savedStock = localStorage.getItem('stock_items');

        if (savedChecklists) setChecklists(JSON.parse(savedChecklists));
        if (savedStock) setStockItems(JSON.parse(savedStock));
    }, []);

    useEffect(() => {
        localStorage.setItem('checklist_entries', JSON.stringify(checklists));
    }, [checklists]);

    // --- CHECK-IN LOGIC ---

    const handleAddResItem = () => {
        if (!tempItem.itemId || tempItem.quantity <= 0) return;
        const stockItem = stockItems.find(i => i.id === tempItem.itemId);
        if (!stockItem) return;

        const newItem = { itemId: stockItem.id, quantity: tempItem.quantity, name: stockItem.name };
        setNewCheckIn(prev => ({
            ...prev,
            itemsReserved: [...(prev.itemsReserved || []), newItem]
        }));
        setTempItem({ itemId: '', quantity: 1 });
    };

    const handleRemoveResItem = (idx: number) => {
        setNewCheckIn(prev => ({
            ...prev,
            itemsReserved: prev.itemsReserved?.filter((_, i) => i !== idx)
        }));
    };

    const handleSaveCheckIn = () => {
        if (!newCheckIn.project || !newCheckIn.technicianCheckIn) {
            alert("Preencha o nome da Obra/Cliente e o Técnico.");
            return;
        }

        const entry: CheckListEntry = {
            id: Date.now().toString(),
            project: newCheckIn.project,
            technicianCheckIn: newCheckIn.technicianCheckIn,
            dateCheckIn: newCheckIn.dateCheckIn || new Date().toISOString().split('T')[0],
            status: 'open',
            itemsReserved: newCheckIn.itemsReserved || []
        };

        // Update Stock Reservations
        const updatedStock = stockItems.map(item => {
            const reserved = entry.itemsReserved.find(r => r.itemId === item.id);
            if (reserved) {
                const newReservation = {
                    id: entry.id,
                    sourceName: entry.project,
                    quantity: reserved.quantity,
                    date: entry.dateCheckIn
                };
                return {
                    ...item,
                    reservedQuantity: (item.reservedQuantity || 0) + reserved.quantity,
                    reservations: [...(item.reservations || []), newReservation]
                };
            }
            return item;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));

        setChecklists(prev => [entry, ...prev]);
        setNewCheckIn({ project: '', technicianCheckIn: '', dateCheckIn: new Date().toISOString().split('T')[0], itemsReserved: [] });
        alert("Check-In realizado com sucesso!");
    };

    // --- CHECK-OUT LOGIC ---

    const handleSelectForCheckout = (checklist: CheckListEntry) => {
        setSelectedChecklist(checklist);
        // Default used items to reserved items
        setCheckoutData({
            dateCheckOut: new Date().toISOString().split('T')[0],
            technicianCheckOut: '',
            itemsUsed: checklist.itemsReserved.map(i => ({ ...i }))
        });
    };

    const handleUsedQtyChange = (idx: number, newQty: number) => {
        setCheckoutData(prev => {
            const newItems = [...prev.itemsUsed];
            newItems[idx].quantity = newQty;
            return { ...prev, itemsUsed: newItems };
        });
    };

    const handleSaveCheckout = () => {
        if (!selectedChecklist || !checkoutData.technicianCheckOut) {
            alert("Informe o técnico responsável pelo Check-Out.");
            return;
        }

        // 1. Close Checklist
        const updatedChecklists = checklists.map(c => 
            c.id === selectedChecklist.id 
            ? { ...c, status: 'closed' as const, dateCheckOut: checkoutData.dateCheckOut, technicianCheckOut: checkoutData.technicianCheckOut, itemsUsed: checkoutData.itemsUsed }
            : c
        );
        setChecklists(updatedChecklists);

        // 2. Update Stock & Generate History
        const currentMovements: StockMovement[] = JSON.parse(localStorage.getItem('stock_movements') || '[]');
        const currentRequests: PurchaseRequest[] = JSON.parse(localStorage.getItem('purchase_requests') || '[]');
        let alertMessages: string[] = [];

        const updatedStock = stockItems.map(item => {
            let newItem = { ...item };

            // A. Remove Reservation associated with this checklist
            if (newItem.reservations) {
                const initialReservation = newItem.reservations.find(r => r.id === selectedChecklist.id);
                if (initialReservation) {
                    newItem.reservedQuantity = Math.max(0, (newItem.reservedQuantity || 0) - initialReservation.quantity);
                    newItem.reservations = newItem.reservations.filter(r => r.id !== selectedChecklist.id);
                }
            }

            // B. Deduct Used Quantity
            const used = checkoutData.itemsUsed.find(u => u.itemId === item.id);
            if (used && used.quantity > 0) {
                newItem.quantity = Math.max(0, newItem.quantity - used.quantity);

                // C. Create Movement Record
                const movement: StockMovement = {
                    id: `mov_${Date.now()}_${item.id}`,
                    itemId: item.id,
                    type: 'saida',
                    quantity: used.quantity,
                    date: checkoutData.dateCheckOut,
                    // FIX: Observation now uses the Project/Client Name explicitly
                    observation: `Obra: ${selectedChecklist.project}`
                };
                currentMovements.unshift(movement);

                // D. Check Min Stock for Auto-Request
                if (newItem.quantity < newItem.minQuantity) {
                    const orderQty = Math.max(newItem.minQuantity * 2, 10);
                    currentRequests.push({
                        id: `req_auto_${Date.now()}_${item.id}`,
                        itemId: item.id,
                        itemName: item.name,
                        quantity: orderQty,
                        unit: item.unit,
                        requester: 'Sistema (Auto)',
                        date: new Date().toISOString().split('T')[0],
                        priority: 'Alta',
                        status: 'Pendente',
                        reason: 'Estoque Mínimo Atingido',
                        observation: `Gerado após Check-Out da obra: ${selectedChecklist.project}`
                    });
                    alertMessages.push(`${item.name} (Estoque atual: ${newItem.quantity})`);
                }
            }
            return newItem;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));
        localStorage.setItem('stock_movements', JSON.stringify(currentMovements));
        localStorage.setItem('purchase_requests', JSON.stringify(currentRequests));

        let msg = "Check-Out realizado com sucesso!";
        if (alertMessages.length > 0) {
            msg += "\n\nAlertas de compra gerados para:\n" + alertMessages.join("\n");
        }
        alert(msg);
        setSelectedChecklist(null);
    };

    // --- VIEW: CHECK-IN ---
    if (view === 'checkin') {
        return (
            <div className="max-w-4xl mx-auto bg-white dark:bg-gray-800 rounded-xl shadow-lg p-8">
                <div className="mb-8 border-b border-gray-200 dark:border-gray-700 pb-4">
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <CheckCircleIcon className="w-8 h-8 text-green-600" />
                        Check-In de Obra (Saída de Materiais)
                    </h2>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">
                        Inicie uma nova obra e reserve os materiais que serão levados a campo.
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Cliente / Obra</label>
                        <input 
                            type="text" 
                            value={newCheckIn.project} 
                            onChange={e => setNewCheckIn({...newCheckIn, project: e.target.value})}
                            className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2.5"
                            placeholder="Ex: Instalação Solar - Sr. João"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Técnico Responsável (Retirada)</label>
                        <input 
                            type="text" 
                            value={newCheckIn.technicianCheckIn} 
                            onChange={e => setNewCheckIn({...newCheckIn, technicianCheckIn: e.target.value})}
                            className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2.5"
                            placeholder="Nome do Técnico"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Data</label>
                        <input 
                            type="date" 
                            value={newCheckIn.dateCheckIn} 
                            onChange={e => setNewCheckIn({...newCheckIn, dateCheckIn: e.target.value})}
                            className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2.5"
                        />
                    </div>
                </div>

                <div className="bg-gray-50 dark:bg-gray-700/30 p-4 rounded-lg border border-gray-200 dark:border-gray-600 mb-6">
                    <h3 className="text-sm font-bold text-gray-800 dark:text-white mb-3 uppercase">Lista de Materiais (Reserva)</h3>

                    <div className="flex gap-2 mb-4">
                        <select 
                            value={tempItem.itemId} 
                            onChange={e => setTempItem({...tempItem, itemId: e.target.value})}
                            className="flex-1 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 text-sm"
                        >
                            <option value="">Selecione um material...</option>
                            {stockItems.map(i => (
                                <option key={i.id} value={i.id}>{i.name} (Disp: {i.quantity - (i.reservedQuantity || 0)})</option>
                            ))}
                        </select>
                        <input 
                            type="number" 
                            min="1"
                            value={tempItem.quantity}
                            onChange={e => setTempItem({...tempItem, quantity: Number(e.target.value)})}
                            className="w-24 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 text-sm"
                            placeholder="Qtd"
                        />
                        <button 
                            onClick={handleAddResItem}
                            className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
                        >
                            <PlusIcon className="w-5 h-5" />
                        </button>
                    </div>

                    <div className="space-y-2 max-h-48 overflow-y-auto">
                        {newCheckIn.itemsReserved && newCheckIn.itemsReserved.length > 0 ? (
                            newCheckIn.itemsReserved.map((item, idx) => (
                                <div key={idx} className="flex justify-between items-center bg-white dark:bg-gray-800 p-2 rounded shadow-sm text-sm border border-gray-200 dark:border-gray-600">
                                    <span className="text-gray-800 dark:text-gray-200 font-medium">{item.name}</span>
                                    <div className="flex items-center gap-3">
                                        <span className="font-bold text-indigo-600 dark:text-indigo-400">{item.quantity}</span>
                                        <button onClick={() => handleRemoveResItem(idx)} className="text-red-500 hover:text-red-700">
                                            <TrashIcon className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <p className="text-gray-500 text-sm italic text-center py-2">Nenhum material adicionado.</p>
                        )}
                    </div>
                </div>

                <div className="flex justify-end">
                    <button 
                        onClick={handleSaveCheckIn}
                        disabled={!newCheckIn.project || (newCheckIn.itemsReserved?.length === 0)}
                        className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors font-medium shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        <SaveIcon className="w-5 h-5" />
                        Confirmar Check-In
                    </button>
                </div>
            </div>
        );
    }

    // --- VIEW: CHECK-OUT ---
    if (view === 'checkout') {
        const activeChecklists = checklists.filter(c => c.status === 'open');

        return (
            <div className="space-y-6">
                {!selectedChecklist ? (
                    <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6">
                        <div className="mb-6">
                            <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                                <ClipboardListIcon className="w-8 h-8 text-indigo-600" />
                                Check-Out de Obra (Retorno)
                            </h2>
                            <p className="text-gray-500 dark:text-gray-400 mt-1">
                                Selecione uma obra aberta para finalizar e confirmar os materiais utilizados.
                            </p>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {activeChecklists.map(checklist => (
                                <div 
                                    key={checklist.id} 
                                    onClick={() => handleSelectForCheckout(checklist)}
                                    className="border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-700/30 rounded-lg p-5 cursor-pointer hover:border-indigo-500 hover:shadow-md transition-all group"
                                >
                                    <div className="flex justify-between items-start mb-2">
                                        <h3 className="font-bold text-lg text-gray-900 dark:text-white group-hover:text-indigo-600">{checklist.project}</h3>
                                        <span className="text-xs font-mono bg-indigo-100 dark:bg-indigo-900 text-indigo-700 dark:text-indigo-300 px-2 py-1 rounded">
                                            {new Date(checklist.dateCheckIn).toLocaleDateString('pt-BR')}
                                        </span>
                                    </div>
                                    <p className="text-sm text-gray-500 dark:text-gray-400 mb-3">Técnico: {checklist.technicianCheckIn}</p>
                                    <div className="text-xs text-gray-500 border-t border-gray-200 dark:border-gray-600 pt-2">
                                        {checklist.itemsReserved.length} itens reservados
                                    </div>
                                </div>
                            ))}
                            {activeChecklists.length === 0 && (
                                <div className="col-span-full py-12 text-center text-gray-500 border-2 border-dashed border-gray-300 rounded-lg">
                                    Nenhuma obra em aberto no momento.
                                </div>
                            )}
                        </div>
                    </div>
                ) : (
                    <div className="max-w-4xl mx-auto bg-white dark:bg-gray-800 rounded-xl shadow-lg p-8 animate-fade-in">
                        <div className="flex justify-between items-center mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                            <div>
                                <h2 className="text-xl font-bold text-gray-900 dark:text-white">Finalizando: {selectedChecklist.project}</h2>
                                <p className="text-sm text-gray-500">Iniciado em {new Date(selectedChecklist.dateCheckIn).toLocaleDateString('pt-BR')} por {selectedChecklist.technicianCheckIn}</p>
                            </div>
                            <button onClick={() => setSelectedChecklist(null)} className="text-sm text-gray-500 hover:text-gray-700 underline">Voltar</button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Técnico (Check-Out)</label>
                                <input 
                                    type="text" 
                                    value={checkoutData.technicianCheckOut} 
                                    onChange={e => setCheckoutData({...checkoutData, technicianCheckOut: e.target.value})}
                                    className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2.5"
                                    placeholder="Quem está finalizando?"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Data Check-Out</label>
                                <input 
                                    type="date" 
                                    value={checkoutData.dateCheckOut} 
                                    onChange={e => setCheckoutData({...checkoutData, dateCheckOut: e.target.value})}
                                    className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2.5"
                                />
                            </div>
                        </div>

                        <div className="bg-yellow-50 dark:bg-yellow-900/10 p-5 rounded-lg border border-yellow-200 dark:border-yellow-800 mb-6">
                            <h3 className="text-sm font-bold text-yellow-800 dark:text-yellow-200 mb-4 flex items-center gap-2">
                                <CubeIcon className="w-5 h-5" />
                                Confirmação de Materiais Utilizados
                            </h3>
                            <div className="space-y-3">
                                <div className="grid grid-cols-12 gap-4 text-xs font-bold text-gray-500 uppercase px-2">
                                    <span className="col-span-6">Material</span>
                                    <span className="col-span-3 text-center">Reservado</span>
                                    <span className="col-span-3 text-center">Utilizado</span>
                                </div>
                                {checkoutData.itemsUsed.map((item, idx) => (
                                    <div key={idx} className="grid grid-cols-12 gap-4 items-center bg-white dark:bg-gray-800 p-3 rounded shadow-sm border border-gray-200 dark:border-gray-600">
                                        <span className="col-span-6 font-medium text-gray-900 dark:text-white">{item.name}</span>
                                        <span className="col-span-3 text-center text-gray-500">{selectedChecklist.itemsReserved[idx].quantity}</span>
                                        <div className="col-span-3">
                                            <input 
                                                type="number" 
                                                min="0"
                                                max={selectedChecklist.itemsReserved[idx].quantity} // Optional: allow using more? usually max reserved or free input
                                                value={item.quantity}
                                                onChange={e => handleUsedQtyChange(idx, Number(e.target.value))}
                                                className="w-full text-center font-bold text-indigo-600 border-gray-300 dark:border-gray-600 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
                                            />
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <p className="text-xs text-yellow-700 dark:text-yellow-400 mt-3">
                                * Ajuste a coluna "Utilizado" com o que realmente foi gasto. A diferença voltará para o estoque disponível.
                            </p>
                        </div>

                        <div className="flex justify-end gap-3">
                            <button 
                                onClick={() => setSelectedChecklist(null)}
                                className="px-6 py-3 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 font-medium"
                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={handleSaveCheckout}
                                className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors font-medium shadow-sm"
                            >
                                <CheckCircleIcon className="w-5 h-5" />
                                Finalizar Obra
                            </button>
                        </div>
                    </div>
                )}
            </div>
        );
    }

    return null;
};

export default CheckListPage;

import React, { useState, useMemo, useEffect } from 'react';
import { ChartPieIcon, PrinterIcon, PlusIcon, TrashIcon, CogIcon, SaveIcon, EditIcon, ClipboardListIcon, CheckCircleIcon, DollarIcon, ExclamationTriangleIcon, DocumentReportIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip as RechartsTooltip, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';
import type { RelatoriosPageProps, ExpenseReportItem, ExpenseReport, ExpenseReportStatus } from '../types';

const RelatoriosPage: React.FC<RelatoriosPageProps> = ({ view, reportToEdit, onSave, onEditReport }) => {
  // --- REIMBURSEMENT STATE ---
  const [solicitante, setSolicitante] = useState('');
  const [setor, setSetor] = useState('');

  // Periodo agora dividido em inicio e fim
  const [periodStart, setPeriodStart] = useState('');
  const [periodEnd, setPeriodEnd] = useState('');

  const [valorPorKm, setValorPorKm] = useState(1.20);

  // State for Config View
  const [configKmValue, setConfigKmValue] = useState(1.20);
  const [isEditingConfig, setIsEditingConfig] = useState(false);
  const [isSuccessModalOpen, setSuccessModalOpen] = useState(false);
  const [modalMessage, setModalMessage] = useState('');

  // State for Payment Confirmation Modal
  const [isPayModalOpen, setPayModalOpen] = useState(false);
  const [reportToPay, setReportToPay] = useState<ExpenseReport | null>(null);

  // State for Transfer Confirmation Modal
  const [isTransferModalOpen, setTransferModalOpen] = useState(false);

  // State for History View
  const [reports, setReports] = useState<ExpenseReport[]>([]);

  // Inicializa com apenas uma linha, conforme solicitado
  const [items, setItems] = useState<ExpenseReportItem[]>([
    { id: '1', date: '', description: '', origin: '', destination: '', km: 0, toll: 0 },
  ]);

  // Load Reports from Storage
  useEffect(() => {
      const savedReports = localStorage.getItem('expense_reports');
      if (savedReports) {
          setReports(JSON.parse(savedReports));
      }
  }, []);

  // Save Reports to Storage
  useEffect(() => {
      localStorage.setItem('expense_reports', JSON.stringify(reports));
  }, [reports]);


  // Load Config/Data based on View and Edit Props
  useEffect(() => {
    if (view === 'reembolso') {
        if (reportToEdit) {
            // Load existing report
            setSolicitante(reportToEdit.requester);
            setSetor(reportToEdit.sector);
            // Load dates if available, otherwise ignore legacy string period
            setPeriodStart(reportToEdit.periodStart || '');
            setPeriodEnd(reportToEdit.periodEnd || '');

            setItems(reportToEdit.items);
            setValorPorKm(reportToEdit.kmValueUsed);
        } else {
            // New report: Reset fields and load default KM value
            setSolicitante('');
            setSetor('');
            setPeriodStart('');
            setPeriodEnd('');
            setItems([{ id: Date.now().toString(), date: '', description: '', origin: '', destination: '', km: 0, toll: 0 }]);

            const savedValue = localStorage.getItem('reembolso_config_km_value');
            if (savedValue) {
                setValorPorKm(parseFloat(savedValue));
            }
        }
    }
  }, [view, reportToEdit]);

  // Load Config for Config View
  useEffect(() => {
    if (view === 'config') {
        const savedValue = localStorage.getItem('reembolso_config_km_value');
        if (savedValue) {
            setConfigKmValue(parseFloat(savedValue));
        }
        setIsEditingConfig(false); 
    }
  }, [view]);

  // Determine if the current report is read-only (Submitted or Paid)
  const isReadOnly = useMemo(() => {
      if (!reportToEdit) return false; // New reports are editable
      return reportToEdit.status === 'Transferido' || reportToEdit.status === 'Pago';
  }, [reportToEdit]);

  const handleAddItem = () => {
    setItems([...items, { id: Date.now().toString(), date: '', description: '', origin: '', destination: '', km: 0, toll: 0 }]);
  };

  const handleRemoveItem = (id: string) => {
    if (items.length > 1) {
      setItems(items.filter(item => item.id !== id));
    }
  };

  const handleItemChange = (id: string, field: keyof ExpenseReportItem, value: string | number) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleSaveConfig = () => {
      localStorage.setItem('reembolso_config_km_value', configKmValue.toString());
      setIsEditingConfig(false);
      setModalMessage("O novo valor do quilômetro foi atualizado com sucesso.");
      setSuccessModalOpen(true);
  }

  const handleCancelConfig = () => {
      const savedValue = localStorage.getItem('reembolso_config_km_value');
      if (savedValue) {
          setConfigKmValue(parseFloat(savedValue));
      }
      setIsEditingConfig(false);
  }

  const totals = useMemo(() => {
    return items.reduce((acc, item) => {
      const reembolsoKm = item.km * valorPorKm;
      const totalRow = reembolsoKm + item.toll;

      return {
        km: acc.km + item.km,
        reembolsoKm: acc.reembolsoKm + reembolsoKm,
        toll: acc.toll + item.toll,
        total: acc.total + totalRow
      };
    }, { km: 0, reembolsoKm: 0, toll: 0, total: 0 });
  }, [items, valorPorKm]);

  // Internal function to execute the save logic
  const executeSave = (targetStatus: ExpenseReportStatus) => {
      // Format Period String for display
      const formatDate = (dateStr: string) => {
          if(!dateStr) return '';
          const [y, m, d] = dateStr.split('-');
          return `${d}/${m}/${y}`;
      };
      const periodString = `${formatDate(periodStart)} a ${formatDate(periodEnd)}`;

      const reportToSave: ExpenseReport = {
          id: reportToEdit ? reportToEdit.id : Date.now().toString(),
          requester: solicitante,
          sector: setor,
          period: periodString,
          periodStart: periodStart,
          periodEnd: periodEnd,
          items: items,
          kmValueUsed: valorPorKm,
          status: targetStatus,
          createdAt: reportToEdit ? reportToEdit.createdAt : new Date().toISOString(),
          totalValue: totals.total
      };

      setReports(prev => {
          if (reportToEdit) {
              return prev.map(r => r.id === reportToSave.id ? reportToSave : r);
          } else {
              return [reportToSave, ...prev];
          }
      });

      setModalMessage(targetStatus === 'Transferido' 
        ? "Relatório transferido com sucesso! Ele agora aguarda pagamento." 
        : "Rascunho salvo com sucesso! Você pode continuar editando depois."
      );
      setSuccessModalOpen(true);

      // Close modal delay
      if (onSave) setTimeout(() => { setSuccessModalOpen(false); onSave(); }, 2000);
      else setTimeout(() => setSuccessModalOpen(false), 2000);
  };

  const handleSaveReportAction = (targetStatus: ExpenseReportStatus) => {
      if (!solicitante || !periodStart || !periodEnd) {
          alert("Preencha o Solicitante e as datas (De/Até) do Período.");
          return;
      }

      if (targetStatus === 'Transferido') {
          setTransferModalOpen(true);
      } else {
          executeSave('Rascunho');
      }
  };

  const handleConfirmTransfer = () => {
      setTransferModalOpen(false);
      executeSave('Transferido');
  }

  const handleDeleteReport = (id: string) => {
      if (window.confirm("Tem certeza que deseja excluir este relatório?")) {
          setReports(prev => prev.filter(r => r.id !== id));
      }
  };

  const handleOpenPayModal = (report: ExpenseReport) => {
      setReportToPay(report);
      setPayModalOpen(true);
  }

  const handleConfirmPay = () => {
      if (reportToPay) {
          setReports(prev => prev.map(r => 
              r.id === reportToPay.id ? { ...r, status: 'Pago' } : r
          ));
          setPayModalOpen(false);
          setReportToPay(null);
      }
  }

  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handlePrint = () => {
    window.print();
  };

  // --- ANALISE METRICS & DATA ---
  const analysisData = useMemo(() => {
      const paid = reports.filter(r => r.status === 'Pago').reduce((acc, r) => acc + r.totalValue, 0);
      const pending = reports.filter(r => r.status === 'Transferido').reduce((acc, r) => acc + r.totalValue, 0);
      const open = reports.filter(r => ['Rascunho', 'Em Aberto'].includes(r.status)).reduce((acc, r) => acc + r.totalValue, 0);

      // Data for Sector Pie Chart
      const sectorMap: Record<string, number> = {};
      reports.forEach(r => {
          if (r.status === 'Pago' || r.status === 'Transferido') {
              const sec = r.sector ? r.sector.toUpperCase() : 'N/A';
              sectorMap[sec] = (sectorMap[sec] || 0) + r.totalValue;
          }
      });
      const sectorData = Object.entries(sectorMap).map(([name, value]) => ({ name, value }));

      // Data for Monthly Bar Chart
      const monthMap: Record<string, number> = {};
      reports.forEach(r => {
          if (r.status === 'Pago' || r.status === 'Transferido') {
              const date = new Date(r.createdAt);
              const key = `${date.getMonth() + 1}/${date.getFullYear()}`;
              monthMap[key] = (monthMap[key] || 0) + r.totalValue;
          }
      });
      const monthlyData = Object.entries(monthMap).map(([name, value]) => ({ name, value }));

      return { paid, pending, open, sectorData, monthlyData };
  }, [reports]);

  const PIE_COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d'];


  // --- VIEW: STATUS (Pending Reports - "Transferido" / "Em Aberto") ---
  if (view === 'status') {
      // Show reports that are Transferred (waiting payment) or Legacy "Em Aberto"
      const pendingReports = reports.filter(r => r.status === 'Transferido' || r.status === 'Em Aberto');

      return (
          <div className="space-y-6">
               <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                   <div className="flex justify-between items-center mb-6">
                       <div>
                           <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                                <CheckCircleIcon className="w-8 h-8 text-indigo-600" />
                                Relatórios Aguardando Pagamento
                           </h2>
                           <p className="text-gray-500 dark:text-gray-400 mt-1">Confirme o pagamento dos relatórios transferidos.</p>
                       </div>
                   </div>

                   <div className="overflow-x-auto">
                       <table className="min-w-full text-left text-sm">
                           <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider">
                               <tr>
                                   <th className="px-6 py-3">Data Criação</th>
                                   <th className="px-6 py-3">Solicitante</th>
                                   <th className="px-6 py-3">Período</th>
                                   <th className="px-6 py-3">Valor Total</th>
                                   <th className="px-6 py-3 text-center">Status</th>
                                   <th className="px-6 py-3 text-center">Ações</th>
                               </tr>
                           </thead>
                           <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                               {pendingReports.map(report => (
                                   <tr key={report.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">
                                           {new Date(report.createdAt).toLocaleDateString('pt-BR')}
                                       </td>
                                       <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{report.requester}</td>
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{report.period}</td>
                                       <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">
                                           {formatCurrency(report.totalValue)}
                                       </td>
                                       <td className="px-6 py-4 text-center">
                                            <span className="px-2 py-1 text-xs font-semibold rounded-full bg-yellow-100 text-yellow-800">
                                                Aguardando Pagamento
                                            </span>
                                       </td>
                                       <td className="px-6 py-4 text-center space-x-2">
                                           <button 
                                               onClick={() => handleOpenPayModal(report)}
                                               className="px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 text-xs font-medium transition-colors shadow-sm"
                                           >
                                               Confirmar Pagamento
                                           </button>
                                       </td>
                                   </tr>
                               ))}
                               {pendingReports.length === 0 && (
                                   <tr>
                                       <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                           Não há relatórios aguardando pagamento.
                                       </td>
                                   </tr>
                               )}
                           </tbody>
                       </table>
                   </div>
               </div>

               {isPayModalOpen && reportToPay && (
                   <Modal title="Confirmar Pagamento" onClose={() => setPayModalOpen(false)}>
                       <div className="space-y-6">
                           <div className="text-center">
                               <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-yellow-100 mb-4">
                                   <span className="text-2xl">?</span>
                               </div>
                               <h3 className="text-lg font-medium text-gray-900 dark:text-white">Confirmar Pagamento</h3>
                               <p className="text-sm text-gray-500 dark:text-gray-400 mt-2">
                                   Deseja confirmar o pagamento do relatório de <strong>{reportToPay.requester}</strong> no valor de <strong>{formatCurrency(reportToPay.totalValue)}</strong>?
                               </p>
                           </div>
                           <div className="flex justify-center gap-4">
                               <button
                                   onClick={() => setPayModalOpen(false)}
                                   className="px-4 py-2 bg-red-100 text-red-700 rounded-md hover:bg-red-200 font-medium transition-colors w-24"
                               >
                                   Não
                               </button>
                               <button
                                   onClick={handleConfirmPay}
                                   className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium transition-colors w-24"
                               >
                                   Sim
                               </button>
                           </div>
                       </div>
                   </Modal>
               )}
          </div>
      );
  }

  // --- VIEW: HISTORY ---
  if (view === 'historico') {
      return (
          <div className="space-y-6">
               <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                   <div className="flex justify-between items-center mb-6">
                       <div>
                           <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                                <ClipboardListIcon className="w-8 h-8 text-indigo-600" />
                                Histórico de Relatórios
                           </h2>
                           <p className="text-gray-500 dark:text-gray-400 mt-1">Acompanhe todos os relatórios gerados.</p>
                       </div>
                   </div>

                   <div className="overflow-x-auto">
                       <table className="min-w-full text-left text-sm">
                           <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider">
                               <tr>
                                   <th className="px-6 py-3">Data Criação</th>
                                   <th className="px-6 py-3">Solicitante</th>
                                   <th className="px-6 py-3">Período</th>
                                   <th className="px-6 py-3">Valor Total</th>
                                   <th className="px-6 py-3 text-center">Status</th>
                                   <th className="px-6 py-3 text-center">Ações</th>
                               </tr>
                           </thead>
                           <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                               {reports.map(report => (
                                   <tr key={report.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">
                                           {new Date(report.createdAt).toLocaleDateString('pt-BR')}
                                       </td>
                                       <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{report.requester}</td>
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{report.period}</td>
                                       <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">
                                           {formatCurrency(report.totalValue)}
                                       </td>
                                       <td className="px-6 py-4 text-center">
                                           <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                                               report.status === 'Pago'
                                               ? 'bg-green-100 text-green-800'
                                               : report.status === 'Transferido'
                                               ? 'bg-yellow-100 text-yellow-800'
                                               : 'bg-gray-200 text-gray-800' // Rascunho / Em Aberto
                                           }`}>
                                               {report.status}
                                            </span>
                                       </td>
                                       <td className="px-6 py-4 text-center space-x-2">
                                           <button 
                                               onClick={() => onEditReport && onEditReport(report)}
                                               className="p-2 text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400"
                                               title={report.status === 'Rascunho' || report.status === 'Em Aberto' ? "Editar" : "Visualizar"}
                                           >
                                               <EditIcon className="w-5 h-5" />
                                           </button>
                                           <button 
                                               onClick={() => handleDeleteReport(report.id)}
                                               className="p-2 text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400"
                                               title="Excluir"
                                           >
                                               <TrashIcon className="w-5 h-5" />
                                           </button>
                                       </td>
                                   </tr>
                               ))}
                               {reports.length === 0 && (
                                   <tr>
                                       <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                           Nenhum relatório salvo no histórico.
                                       </td>
                                   </tr>
                               )}
                           </tbody>
                       </table>
                   </div>
               </div>
          </div>
      );
  }

  // --- VIEW: CONFIG ---
  if (view === 'config') {
      return (
          <div className="max-w-xl mx-auto space-y-6">
              <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-lg">
                  <div className="flex items-center gap-4 mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                      <div className="p-3 bg-indigo-100 dark:bg-indigo-900 rounded-full">
                          <CogIcon className="w-8 h-8 text-indigo-600 dark:text-indigo-400" />
                      </div>
                      <div>
                          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Cadastro de KM</h2>
                          <p className="text-gray-500 dark:text-gray-400">Defina o valor padrão a ser pago por quilômetro rodado nos relatórios de despesa.</p>
                      </div>
                  </div>

                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Valor por Quilômetro (R$)</label>
                          <div className="relative rounded-md shadow-sm">
                              <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                                  <span className="text-gray-500 sm:text-sm">R$</span>
                              </div>
                              <input
                                  type="number"
                                  step="0.01"
                                  min="0"
                                  value={configKmValue}
                                  onChange={(e) => setConfigKmValue(parseFloat(e.target.value))}
                                  disabled={!isEditingConfig}
                                  className={`block w-full rounded-md border-gray-300 dark:border-gray-600 pl-10 focus:ring-indigo-500 focus:border-indigo-500 sm:text-lg py-3 transition-colors ${
                                      !isEditingConfig 
                                      ? 'bg-gray-100 dark:bg-gray-700 text-gray-500 cursor-not-allowed' 
                                      : 'bg-white dark:bg-gray-600 text-gray-900 dark:text-white'
                                  }`}
                                  placeholder="0.00"
                              />
                          </div>
                          <p className="mt-2 text-sm text-gray-500">
                              Este valor será carregado automaticamente ao criar um novo relatório.
                          </p>
                      </div>

                      <div className="pt-4 flex justify-end gap-3">
                          {!isEditingConfig ? (
                              <button
                                  onClick={() => setIsEditingConfig(true)}
                                  className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium shadow-md"
                              >
                                  <EditIcon className="w-5 h-5" />
                                  Editar Valor
                              </button>
                          ) : (
                              <>
                                  <button
                                      onClick={handleCancelConfig}
                                      className="px-6 py-3 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors font-medium"
                                  >
                                      Cancelar
                                  </button>
                                  <button
                                      onClick={handleSaveConfig}
                                      className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium shadow-md"
                                  >
                                      <SaveIcon className="w-5 h-5" />
                                      Salvar
                                  </button>
                              </>
                          )}
                      </div>
                  </div>
              </div>

              {isSuccessModalOpen && (
                <Modal title="Sucesso" onClose={() => setSuccessModalOpen(false)}>
                    <div className="text-center space-y-4 py-4">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100">
                            <svg className="h-6 w-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path>
                            </svg>
                        </div>
                        <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">Alteração Salva</h3>
                        <p className="text-sm text-gray-500 dark:text-gray-400">
                            {modalMessage}
                        </p>
                        <div className="mt-6">
                            <button
                                type="button"
                                className="inline-flex justify-center w-full rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 sm:text-sm"
                                onClick={() => setSuccessModalOpen(false)}
                            >
                                OK
                            </button>
                        </div>
                    </div>
                </Modal>
              )}
          </div>
      );
  }

  // --- VIEW: ANALISE (Dashboard) ---
  if (view === 'analise') {
    return (
        <div className="space-y-6">
             <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                <DashboardCard title="Reembolsos Pagos" value={formatCurrency(analysisData.paid)} icon={CheckCircleIcon} color="bg-green-500" />
                <DashboardCard title="Aguardando Pagamento" value={formatCurrency(analysisData.pending)} icon={ExclamationTriangleIcon} color="bg-yellow-500" />
                <DashboardCard title="Em Aberto (Rascunhos)" value={formatCurrency(analysisData.open)} icon={DocumentReportIcon} color="bg-gray-500" />
             </div>

             <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                 {/* Sector Chart */}
                 <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg min-h-[400px]">
                     <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Despesas por Setor</h3>
                     {analysisData.sectorData.length > 0 ? (
                         <ResponsiveContainer width="100%" height={300}>
                             <PieChart>
                                 <Pie
                                     data={analysisData.sectorData}
                                     cx="50%"
                                     cy="50%"
                                     innerRadius={60}
                                     outerRadius={100}
                                     fill="#8884d8"
                                     paddingAngle={5}
                                     dataKey="value"
                                     label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                                 >
                                     {analysisData.sectorData.map((entry, index) => (
                                         <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                                     ))}
                                 </Pie>
                                 <RechartsTooltip formatter={(value) => formatCurrency(Number(value))} />
                                 <Legend />
                             </PieChart>
                         </ResponsiveContainer>
                     ) : (
                         <div className="h-full flex flex-col items-center justify-center text-gray-400">
                             <ChartPieIcon className="w-16 h-16 mb-2 opacity-50" />
                             <p>Sem dados de setores registrados.</p>
                         </div>
                     )}
                 </div>

                 {/* Monthly Chart */}
                 <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg min-h-[400px]">
                     <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Evolução Mensal (Pagos e Transferidos)</h3>
                     {analysisData.monthlyData.length > 0 ? (
                         <ResponsiveContainer width="100%" height={300}>
                             <BarChart data={analysisData.monthlyData}>
                                 <CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.3} />
                                 <XAxis dataKey="name" tick={{fill: '#9CA3AF'}} />
                                 <YAxis tick={{fill: '#9CA3AF'}} />
                                 <RechartsTooltip 
                                    contentStyle={{ backgroundColor: '#1F2937', borderColor: '#374151', color: '#F3F4F6' }}
                                    formatter={(value) => [formatCurrency(Number(value)), 'Valor']}
                                 />
                                 <Bar dataKey="value" fill="#6366F1" radius={[4, 4, 0, 0]} />
                             </BarChart>
                         </ResponsiveContainer>
                     ) : (
                         <div className="h-full flex flex-col items-center justify-center text-gray-400">
                             <DollarIcon className="w-16 h-16 mb-2 opacity-50" />
                             <p>Sem dados mensais disponíveis.</p>
                         </div>
                     )}
                 </div>
             </div>
        </div>
    );
  }

  // --- VIEW: REEMBOLSO (New/Edit/View) ---
  return (
    <div className="space-y-6">
        <div className="bg-white dark:bg-gray-800 p-4 sm:p-8 rounded-xl shadow-lg animate-fade-in print:shadow-none print:p-0">

            {/* Action Bar */}
            <div className="flex justify-between items-center mb-6 print:hidden">
                <div className="flex items-center gap-2">
                     {reportToEdit && (
                        <div className={`px-3 py-1 rounded-full text-xs font-semibold ${
                            reportToEdit.status === 'Pago' ? 'bg-green-100 text-green-800' : 
                            reportToEdit.status === 'Transferido' ? 'bg-yellow-100 text-yellow-800' :
                            'bg-gray-200 text-gray-800'
                        }`}>
                            Status: {reportToEdit.status}
                        </div>
                     )}
                     {isReadOnly && (
                         <span className="text-xs text-red-500 font-medium ml-2">
                             (Somente Leitura)
                         </span>
                     )}
                </div>
                <div className="flex gap-3">
                    {!isReadOnly ? (
                        <>
                            <button 
                                onClick={() => handleSaveReportAction('Rascunho')}
                                className="flex items-center gap-2 px-4 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 transition-colors shadow-sm"
                            >
                                <SaveIcon className="w-5 h-5" />
                                Salvar Rascunho
                            </button>
                            <button 
                                onClick={() => handleSaveReportAction('Transferido')}
                                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"
                            >
                                <CheckCircleIcon className="w-5 h-5" />
                                Salvar e Transferir
                            </button>
                        </>
                    ) : (
                         <div className="text-sm text-gray-500 italic mr-2 flex items-center">
                             Este relatório já foi finalizado.
                         </div>
                    )}
                    <button 
                        onClick={handlePrint}
                        className="flex items-center gap-2 px-4 py-2 bg-gray-800 text-white rounded-md hover:bg-gray-900 transition-colors shadow-sm"
                    >
                        <PrinterIcon className="w-5 h-5" />
                        Imprimir
                    </button>
                </div>
            </div>

            {/* REPORT CONTAINER - Neutral Theme */}
            <div className={`border border-gray-300 bg-white text-gray-900 print:border-none shadow-sm ${isReadOnly ? 'opacity-90' : ''}`}>

                {/* 1. Header Section - Clean & Neutral */}
                <div className="p-6 border-b border-gray-300 bg-gray-50 flex items-center justify-center">
                    <h1 className="text-2xl font-bold text-gray-800 uppercase tracking-wide">Relatório de Reembolso de Despesas</h1>
                </div>

                {/* 2. Inputs Section */}
                <div className="p-6 grid grid-cols-12 gap-6 bg-white">
                    <div className="col-span-12 md:col-span-6 space-y-3">
                         <div className="flex items-center">
                             <label className="w-40 font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Nome Solicitante</label>
                             <input 
                                type="text" 
                                value={solicitante}
                                onChange={(e) => setSolicitante(e.target.value)}
                                disabled={isReadOnly}
                                className="flex-1 border border-gray-300 border-l-0 px-3 py-2 outline-none focus:bg-gray-50 text-sm transition-colors disabled:bg-gray-50 disabled:text-gray-500"
