                                    disabled={isReadOnly}
                                    className="outline-none text-sm bg-transparent text-gray-700 font-medium disabled:text-gray-500"
                                />
                             </div>
                         </div>
                    </div>

                    <div className="col-span-12 md:col-span-6 flex flex-col items-end">
                        <div className="flex items-center">
                             <label className="font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Reembolso por Km</label>
