                                 <span className="text-sm mr-1 text-gray-500">R$</span>
                                 <input 
                                    type="number" 
                                    step="0.01"
                                    value={valorPorKm}
                                    readOnly
                                    className="w-full outline-none text-right font-medium text-sm bg-transparent text-gray-600 cursor-not-allowed"
                                 />
                             </div>
                        </div>
                    </div>
                </div>

                {/* 3. Table Section */}
                <div className="overflow-x-auto p-6 pt-0">
                    <table className="w-full border-collapse border border-gray-300 text-sm">
                        <thead>
                            <tr className="bg-gray-100 text-gray-700 font-bold text-center">
                                <th className="border border-gray-300 p-2 w-28">Data</th>
                                <th className="border border-gray-300 p-2">Descrição da Viagem</th>
                                <th className="border border-gray-300 p-2 w-32">Origem</th>
                                <th className="border border-gray-300 p-2 w-32">Destino</th>
                                <th className="border border-gray-300 p-2 w-24">Km Rodado</th>
                                <th className="border border-gray-300 p-2 w-28">Reembolso Km</th>
                                <th className="border border-gray-300 p-2 w-24">Pedágio</th>
                                <th className="border border-gray-300 p-2 w-28">Total Reembolso</th>
                                <th className="border border-gray-300 p-1 w-8 print:hidden"></th>
                            </tr>
                        </thead>
                        <tbody>
                            {items.map((item) => {
                                const reembolsoItem = item.km * valorPorKm;
                                const totalItem = reembolsoItem + item.toll;

                                return (
                                    <tr key={item.id} className="text-center group hover:bg-gray-50">
                                        <td className="border border-gray-300 p-0">
                                            <input 
                                                type="date" 
                                                className="w-full h-full p-2 text-center outline-none bg-transparent disabled:text-gray-500"
                                                value={item.date}
