                                        <td className="border border-gray-300 p-0">
                                            <input 
                                                type="text" 
                                                className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500"
                                                value={item.description}
                                                onChange={(e) => handleItemChange(item.id, 'description', e.target.value)}
                                                disabled={isReadOnly}
                                            />
                                        </td>
                                        <td className="border border-gray-300 p-0">
                                            <input 
                                                type="text" 
                                                className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500"
                                                value={item.origin}
                                                onChange={(e) => handleItemChange(item.id, 'origin', e.target.value)}
                                                disabled={isReadOnly}
                                            />
                                        </td>
                                        <td className="border border-gray-300 p-0">
                                            <input 
                                                type="text" 
                                                className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500"
                                                value={item.destination}
                                                onChange={(e) => handleItemChange(item.id, 'destination', e.target.value)}
                                                disabled={isReadOnly}
                                            />
                                        </td>
                                        <td className="border border-gray-300 p-0">
                                            <input 
                                                type="number" 
                                                className="w-full h-full p-2 text-center outline-none bg-transparent disabled:text-gray-500"
                                                value={item.km || ''}
                                                onChange={(e) => handleItemChange(item.id, 'km', parseFloat(e.target.value) || 0)}
                                                disabled={isReadOnly}
                                            />
                                        </td>
                                        <td className="border border-gray-300 p-2 bg-gray-50 text-gray-700 font-medium">
                                            {formatCurrency(reembolsoItem)}
                                        </td>
                                        <td className="border border-gray-300 p-0">
                                            <div className="flex items-center h-full px-1">
                                                <span className="text-xs text-gray-400 mr-1">R$</span>
                                                <input 
                                                    type="number" 
                                                    className="w-full h-full py-2 text-right outline-none bg-transparent disabled:text-gray-500"
                                                    value={item.toll || ''}
                                                    onChange={(e) => handleItemChange(item.id, 'toll', parseFloat(e.target.value) || 0)}
                                                    disabled={isReadOnly}
                                                />
                                            </div>
                                        </td>
                                        <td className="border border-gray-300 p-2 bg-gray-100 font-bold text-gray-900">
                                            {formatCurrency(totalItem)}
                                        </td>
                                        <td className="border border-gray-300 p-0 print:hidden">
                                            {!isReadOnly && (
                                                <button 
                                                    onClick={() => handleRemoveItem(item.id)}
                                                    className="w-full h-full flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 transition-colors"
                                                    title="Remover linha"
                                                >
                                                    <TrashIcon className="w-4 h-4" />
                                                </button>
                                            )}
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                        <tfoot>
                            <tr className="bg-gray-200 font-bold text-gray-800">
                                <td colSpan={4} className="border border-gray-300 p-2 text-right pr-4 uppercase text-xs tracking-wider">Total Geral</td>
                                <td className="border border-gray-300 p-2 text-center">{totals.km}</td>
                                <td className="border border-gray-300 p-2 text-center">{formatCurrency(totals.reembolsoKm)}</td>
                                <td className="border border-gray-300 p-2 text-center">{formatCurrency(totals.toll)}</td>
                                <td className="border border-gray-300 p-2 text-center text-gray-900 bg-gray-300">{formatCurrency(totals.total)}</td>
                                <td className="border border-gray-300 p-1 print:hidden"></td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            </div>

            {/* Add Row Button */}
            {!isReadOnly && (
                <div className="mt-4 print:hidden">
                    <button
                        onClick={handleAddItem}
                        className="flex items-center gap-2 px-4 py-2 bg-white text-indigo-600 rounded-md border border-indigo-200 hover:bg-indigo-50 hover:border-indigo-300 transition-colors shadow-sm"
                    >
                        <PlusIcon className="w-4 h-4" />
                        Adicionar Linha
                    </button>
                </div>
            )}

            <div className="mt-8 text-xs text-gray-400 text-center print:block hidden">
                Relatório gerado pelo sistema Orner em {new Date().toLocaleDateString('pt-BR')}
            </div>
        </div>

        {/* Modal de Sucesso */}
        {isSuccessModalOpen && (
            <Modal title="Sucesso" onClose={() => setSuccessModalOpen(false)}>
                <div className="text-center space-y-4 py-4">
                    <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100">
                        <svg className="h-6 w-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path>
                        </svg>
                    </div>
                    <h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">Ação Realizada</h3>
                    <p className="text-sm text-gray-500 dark:text-gray-400">
                        {modalMessage}
                    </p>
                    <div className="mt-6">
                        <button
                            type="button"
                            className="inline-flex justify-center w-full rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 sm:text-sm"
                            onClick={() => setSuccessModalOpen(false)}
                        >
                            OK
                        </button>
                    </div>
                </div>
            </Modal>
        )}

        {/* Modal Confirmação de Transferência */}
        {isTransferModalOpen && (
            <Modal title="Confirmar Transferência" onClose={() => setTransferModalOpen(false)}>
                <div className="space-y-6">
                    <div className="text-center">
                        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-yellow-100 mb-4">
                            <span className="text-2xl font-bold text-yellow-600">?</span>
                        </div>
                        <h3 className="text-lg font-medium text-gray-900 dark:text-white">Deseja Realmente Transferir?</h3>
                        <p className="text-sm text-gray-500 dark:text-gray-400 mt-2">
                            Ao transferir, o relatório será finalizado e você <strong>não poderá mais alterá-lo</strong>.
                        </p>
                    </div>
                    <div className="flex justify-center gap-4">
                        <button
                            onClick={() => setTransferModalOpen(false)}
                            className="px-6 py-2 bg-red-100 text-red-700 rounded-md hover:bg-red-200 font-medium transition-colors w-24"
                        >
                            Não
                        </button>
                        <button
                            onClick={handleConfirmTransfer}
                            className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium transition-colors w-24"
                        >
                            Sim
                        </button>
                    </div>
                </div>
            </Modal>
        )}
    </div>
  );
};

export default RelatoriosPage;

import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ClipboardListIcon, SaveIcon, TrashIcon, CubeIcon, PlusIcon, XCircleIcon } from '../assets/icons';
import type { CheckListPageProps, StockItem, StockMovement, PurchaseRequest } from '../types';
import Modal from '../components/Modal';

interface CheckListEntry {
    id: string;
    project: string;
    technicianCheckIn: string;
    dateCheckIn: string;
    status: 'open' | 'closed';
    itemsReserved: { itemId: string; quantity: number; name: string }[];

    // Checkout data
    dateCheckOut?: string;
    technicianCheckOut?: string;
    itemsUsed?: { itemId: string; quantity: number; name: string }[];
}

const CheckListPage: React.FC<CheckListPageProps> = ({ view }) => {
    const [checklists, setChecklists] = useState<CheckListEntry[]>([]);
    const [stockItems, setStockItems] = useState<StockItem[]>([]);

    // State Check-In
    const [newCheckIn, setNewCheckIn] = useState<Partial<CheckListEntry>>({
        project: '',
        technicianCheckIn: '',
        dateCheckIn: new Date().toISOString().split('T')[0],
        itemsReserved: []
    });
    const [tempItem, setTempItem] = useState({ itemId: '', quantity: 1 });

    // State Check-Out
    const [selectedChecklist, setSelectedChecklist] = useState<CheckListEntry | null>(null);
    const [checkoutData, setCheckoutData] = useState({
        dateCheckOut: new Date().toISOString().split('T')[0],
        technicianCheckOut: '',
        itemsUsed: [] as { itemId: string; quantity: number; name: string }[]
    });

    useEffect(() => {
        try {
            const savedChecklists = localStorage.getItem('checklist_entries');
            const savedStock = localStorage.getItem('stock_items');

            if (savedChecklists) {
                const parsed = JSON.parse(savedChecklists);
                if (Array.isArray(parsed)) setChecklists(parsed);
            }
            if (savedStock) {
                const parsed = JSON.parse(savedStock);
                if (Array.isArray(parsed)) setStockItems(parsed);
            }
        } catch (e) {
            console.error("Erro ao carregar dados:", e);
        }
    }, []);

    useEffect(() => {
        localStorage.setItem('checklist_entries', JSON.stringify(checklists));
    }, [checklists]);

    // --- LOGIC: CHECK-IN ---
    const handleAddResItem = () => {
        if (!tempItem.itemId || tempItem.quantity <= 0) return;
        const stockItem = stockItems.find(i => i.id === tempItem.itemId);
        if (!stockItem) return;

        // Verifica se já não adicionou este item
        const existing = newCheckIn.itemsReserved?.find(i => i.itemId === stockItem.id);
        if (existing) {
            alert("Este item já está na lista. Remova-o para alterar a quantidade.");
            return;
        }

        const newItem = { itemId: stockItem.id, quantity: tempItem.quantity, name: stockItem.name };
        setNewCheckIn(prev => ({
            ...prev,
            itemsReserved: [...(prev.itemsReserved || []), newItem]
        }));
        setTempItem({ itemId: '', quantity: 1 });
    };

    const handleRemoveResItem = (idx: number) => {
        setNewCheckIn(prev => ({
            ...prev,
            itemsReserved: prev.itemsReserved?.filter((_, i) => i !== idx)
        }));
    };

    const handleSaveCheckIn = () => {
        if (!newCheckIn.project || !newCheckIn.technicianCheckIn) {
            alert("Preencha o nome da Obra/Cliente e o Técnico.");
            return;
        }

        const entry: CheckListEntry = {
            id: Date.now().toString(),
            project: newCheckIn.project!,
            technicianCheckIn: newCheckIn.technicianCheckIn!,
            dateCheckIn: newCheckIn.dateCheckIn || new Date().toISOString().split('T')[0],
            status: 'open',
            itemsReserved: newCheckIn.itemsReserved || []
        };

        // Atualiza reserva no estoque
        const updatedStock = stockItems.map(item => {
            const reserved = entry.itemsReserved.find(r => r.itemId === item.id);
            if (reserved) {
                const newReservation = {
                    id: entry.id,
                    sourceName: entry.project,
                    quantity: reserved.quantity,
                    date: entry.dateCheckIn
                };
                return {
                    ...item,
                    reservedQuantity: (item.reservedQuantity || 0) + reserved.quantity,
                    reservations: [...(item.reservations || []), newReservation]
                };
            }
            return item;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));

        setChecklists(prev => [entry, ...prev]);
        setNewCheckIn({ project: '', technicianCheckIn: '', dateCheckIn: new Date().toISOString().split('T')[0], itemsReserved: [] });
        alert("Check-In salvo com sucesso!");
    };

    // --- LOGIC: CHECK-OUT ---
    const handleSelectForCheckout = (checklist: CheckListEntry) => {
        setSelectedChecklist(checklist);
        setCheckoutData({
            dateCheckOut: new Date().toISOString().split('T')[0],
            technicianCheckOut: '',
            itemsUsed: (checklist.itemsReserved || []).map(i => ({ ...i }))
        });
    };

    const handleUsedQtyChange = (idx: number, newQty: number) => {
        setCheckoutData(prev => {
            const newItems = [...prev.itemsUsed];
            if (newItems[idx]) {
                newItems[idx].quantity = newQty;
            }
            return { ...prev, itemsUsed: newItems };
        });
    };

    const handleSaveCheckout = () => {
        if (!selectedChecklist || !checkoutData.technicianCheckOut) {
            alert("Informe o técnico responsável pelo Check-Out.");
            return;
        }

        // 1. Fecha o Checklist
        const updatedChecklists = checklists.map(c => 
            c.id === selectedChecklist.id 
            ? { ...c, status: 'closed' as const, dateCheckOut: checkoutData.dateCheckOut, technicianCheckOut: checkoutData.technicianCheckOut, itemsUsed: checkoutData.itemsUsed }
            : c
        );
        setChecklists(updatedChecklists);

        // 2. Atualiza Estoque e Movimentações
        const currentMovements: StockMovement[] = JSON.parse(localStorage.getItem('stock_movements') || '[]');

        const updatedStock = stockItems.map(item => {
            let newItem = { ...item };

            // Remove Reserva
            if (newItem.reservations) {
                const initialReservation = newItem.reservations.find(r => r.id === selectedChecklist.id);
                if (initialReservation) {
                    newItem.reservedQuantity = Math.max(0, (newItem.reservedQuantity || 0) - initialReservation.quantity);
                    newItem.reservations = newItem.reservations.filter(r => r.id !== selectedChecklist.id);
                }
            }

            // Consome Estoque Real
            const used = checkoutData.itemsUsed.find(u => u.itemId === item.id);
            if (used && used.quantity > 0) {
                newItem.quantity = Math.max(0, newItem.quantity - used.quantity);

                // Registra Saída
                currentMovements.unshift({
                    id: `mov_out_${Date.now()}_${item.id}`,
                    itemId: item.id,
                    type: 'saida',
                    quantity: used.quantity,
                    date: checkoutData.dateCheckOut,
                    observation: `Check-Out Obra: ${selectedChecklist.project}`
                });
            }
            return newItem;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));
        localStorage.setItem('stock_movements', JSON.stringify(currentMovements));

        alert("Check-Out finalizado com sucesso!");
        setSelectedChecklist(null);
    };

    // --- RENDER ---

    if (view === 'checkin') {
        return (
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 max-w-4xl mx-auto">
                <div className="mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <CheckCircleIcon className="w-8 h-8 text-green-600" />
                        Check-In (Saída para Obra)
                    </h2>
                </div>

                <div className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Cliente / Obra</label>
                            <input 
                                type="text" 
                                value={newCheckIn.project} 
                                onChange={e => setNewCheckIn({...newCheckIn, project: e.target.value})}
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                                placeholder="Nome da Obra"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Técnico Responsável</label>
                            <input 
                                type="text" 
                                value={newCheckIn.technicianCheckIn} 
                                onChange={e => setNewCheckIn({...newCheckIn, technicianCheckIn: e.target.value})}
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                                placeholder="Quem retirou?"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Data</label>
                            <input 
                                type="date" 
                                value={newCheckIn.dateCheckIn} 
                                onChange={e => setNewCheckIn({...newCheckIn, dateCheckIn: e.target.value})}
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            />
                        </div>
                    </div>

                    <div className="bg-gray-50 dark:bg-gray-700/50 p-4 rounded-lg border border-gray-200 dark:border-gray-600">
                        <h4 className="font-bold text-gray-800 dark:text-white mb-3 text-sm uppercase">Adicionar Materiais</h4>
                        <div className="flex gap-2">
                             <select 
                                value={tempItem.itemId} 
                                onChange={e => setTempItem({...tempItem, itemId: e.target.value})}
                                className="flex-1 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 text-sm"
                            >
                                <option value="">Selecione...</option>
                                {stockItems.map(i => (
                                    <option key={i.id} value={i.id}>{i.name} (Disp: {(i.quantity - (i.reservedQuantity || 0))})</option>
                                ))}
                            </select>
                            <input 
                                type="number" 
                                min="1"
                                value={tempItem.quantity}
                                onChange={e => setTempItem({...tempItem, quantity: Number(e.target.value)})}
                                className="w-24 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 text-sm"
                            />
                            <button 
                                onClick={handleAddResItem}
                                className="px-4 bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
                            >
                                <PlusIcon className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    {newCheckIn.itemsReserved && newCheckIn.itemsReserved.length > 0 && (
                        <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
                            <table className="min-w-full text-sm text-left">
                                <thead className="bg-gray-100 dark:bg-gray-700">
                                    <tr>
                                        <th className="px-4 py-2">Item</th>
                                        <th className="px-4 py-2 text-center">Qtd</th>
                                        <th className="px-4 py-2 w-10"></th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {newCheckIn.itemsReserved.map((item, idx) => (
                                        <tr key={idx} className="border-b dark:border-gray-700 last:border-0">
                                            <td className="px-4 py-2">{item.name}</td>
                                            <td className="px-4 py-2 text-center font-bold">{item.quantity}</td>
                                            <td className="px-4 py-2 text-center">
                                                <button onClick={() => handleRemoveResItem(idx)} className="text-red-500 hover:text-red-700">
                                                    <TrashIcon className="w-4 h-4" />
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}

                    <div className="flex justify-end pt-4">
                        <button 
                            onClick={handleSaveCheckIn}
                            className="flex items-center gap-2 px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium shadow-sm"
                        >
                            <SaveIcon className="w-5 h-5" />
                            Salvar Check-In
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    if (view === 'checkout') {
        const activeChecklists = checklists.filter(c => c.status === 'open');

        if (selectedChecklist) {
            return (
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 max-w-4xl mx-auto">
                    <div className="flex justify-between items-center mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white">Finalizar: {selectedChecklist.project}</h2>
                        <button onClick={() => setSelectedChecklist(null)} className="text-gray-500 hover:text-gray-700 text-sm underline">Voltar</button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Técnico (Check-Out)</label>
                            <input 
                                type="text" 
                                value={checkoutData.technicianCheckOut} 
