                    <p className="text-gray-500 mt-1">Selecione uma obra em andamento para finalizar.</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {activeChecklists.length === 0 ? (
                        <div className="col-span-full text-center py-10 text-gray-500 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-lg">
                            Nenhuma obra em aberto.
