import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ClipboardListIcon, SaveIcon, TrashIcon, CubeIcon, PlusIcon } from '../assets/icons';
import type { CheckListPageProps, StockItem, StockMovement } from '../types';

interface CheckListEntry {
    id: string;
    project: string;
    technicianCheckIn: string;
    dateCheckIn: string;
    status: 'open' | 'closed';
    itemsReserved: { itemId: string; quantity: number; name: string }[];

    // Checkout data
    dateCheckOut?: string;
    technicianCheckOut?: string;
    itemsUsed?: { itemId: string; quantity: number; name: string }[];
}

const CheckListPage: React.FC<CheckListPageProps> = ({ view }) => {
    // --- ESTADOS ---
    const [checklists, setChecklists] = useState<CheckListEntry[]>([]);
    const [stockItems, setStockItems] = useState<StockItem[]>([]);

    // Estado do Formulário de Check-In
    const [newCheckIn, setNewCheckIn] = useState<{
        project: string;
        technician: string;
        date: string;
        items: { itemId: string; quantity: number; name: string }[];
    }>({
        project: '',
        technician: '',
        date: new Date().toISOString().split('T')[0],
        items: []
    });

    // Estado temporário para adicionar item no Check-In
    const [selectedItemToAdd, setSelectedItemToAdd] = useState('');
    const [quantityToAdd, setQuantityToAdd] = useState(1);

    // Estado do Check-Out
    const [checklistToCheckout, setChecklistToCheckout] = useState<CheckListEntry | null>(null);
    const [checkoutForm, setCheckoutForm] = useState<{
        technician: string;
        date: string;
        itemsUsed: { itemId: string; quantity: number; name: string }[];
    }>({
        technician: '',
        date: new Date().toISOString().split('T')[0],
        itemsUsed: []
    });

    // --- CARREGAMENTO DE DADOS ---
    useEffect(() => {
        try {
            const storedChecklists = localStorage.getItem('checklist_entries');
            const storedStock = localStorage.getItem('stock_items');

            if (storedChecklists) setChecklists(JSON.parse(storedChecklists));
            if (storedStock) setStockItems(JSON.parse(storedStock));
        } catch (error) {
            console.error("Erro ao carregar dados:", error);
        }
    }, []);

    // --- SALVAMENTO AUTOMÁTICO ---
    useEffect(() => {
        if (checklists.length > 0) {
            localStorage.setItem('checklist_entries', JSON.stringify(checklists));
        }
    }, [checklists]);

    // --- FUNÇÕES DE CHECK-IN ---

    const addItemToCheckIn = () => {
        if (!selectedItemToAdd || quantityToAdd <= 0) return;

        const stockItem = stockItems.find(i => i.id === selectedItemToAdd);
        if (!stockItem) return;

        // Verifica duplicidade na lista
        if (newCheckIn.items.some(i => i.itemId === selectedItemToAdd)) {
            alert("Este item já foi adicionado à lista.");
            return;
        }

        const newItem = {
            itemId: stockItem.id,
            quantity: quantityToAdd,
            name: stockItem.name
        };

        setNewCheckIn(prev => ({
            ...prev,
            items: [...prev.items, newItem]
        }));

        // Reset inputs
        setSelectedItemToAdd('');
        setQuantityToAdd(1);
    };

    const removeItemFromCheckIn = (index: number) => {
        setNewCheckIn(prev => ({
            ...prev,
            items: prev.items.filter((_, i) => i !== index)
        }));
    };

    const saveCheckIn = () => {
        if (!newCheckIn.project || !newCheckIn.technician || newCheckIn.items.length === 0) {
            alert("Preencha todos os campos e adicione pelo menos um item.");
            return;
        }

        const newEntry: CheckListEntry = {
            id: Date.now().toString(),
            project: newCheckIn.project,
            technicianCheckIn: newCheckIn.technician,
            dateCheckIn: newCheckIn.date,
            status: 'open',
            itemsReserved: newCheckIn.items
        };

        // Atualizar Estoque (Reservar Itens)
        const updatedStock = stockItems.map(item => {
            const reserved = newCheckIn.items.find(i => i.itemId === item.id);
            if (reserved) {
                return {
                    ...item,
                    reservedQuantity: (item.reservedQuantity || 0) + reserved.quantity,
                    reservations: [
                        ...(item.reservations || []),
                        {
                            id: newEntry.id,
                            sourceName: newEntry.project,
                            quantity: reserved.quantity,
                            date: newEntry.dateCheckIn
                        }
                    ]
                };
            }
            return item;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));

        setChecklists(prev => [newEntry, ...prev]);
        setNewCheckIn({
            project: '',
            technician: '',
            date: new Date().toISOString().split('T')[0],
            items: []
        });

        alert("Check-In realizado com sucesso!");
    };

    // --- FUNÇÕES DE CHECK-OUT ---

    const startCheckout = (checklist: CheckListEntry) => {
        setChecklistToCheckout(checklist);
        setCheckoutForm({
            technician: '',
            date: new Date().toISOString().split('T')[0],
            itemsUsed: checklist.itemsReserved.map(i => ({ ...i })) // Copia inicial: usou tudo que reservou
        });
    };

    const updateUsedQuantity = (index: number, qty: number) => {
        setCheckoutForm(prev => {
            const newItems = [...prev.itemsUsed];
            newItems[index].quantity = qty;
            return { ...prev, itemsUsed: newItems };
        });
    };

    const saveCheckout = () => {
        if (!checklistToCheckout || !checkoutForm.technician) {
            alert("Informe o técnico responsável pelo retorno.");
            return;
        }

        // 1. Atualizar Checklist para Fechado
        const updatedChecklists = checklists.map(c => 
            c.id === checklistToCheckout.id 
            ? { 
                ...c, 
                status: 'closed' as const, 
                dateCheckOut: checkoutForm.date, 
                technicianCheckOut: checkoutForm.technician, 
                itemsUsed: checkoutForm.itemsUsed 
              }
            : c
        );
        setChecklists(updatedChecklists);

        // 2. Atualizar Estoque (Remover Reserva e Baixar Estoque Real)
        const movements: StockMovement[] = JSON.parse(localStorage.getItem('stock_movements') || '[]');

        const updatedStock = stockItems.map(item => {
            let newItem = { ...item };

            // A. Remove a reserva específica deste checklist
            if (newItem.reservations) {
                const reservation = newItem.reservations.find(r => r.id === checklistToCheckout.id);
                if (reservation) {
                    newItem.reservedQuantity = Math.max(0, (newItem.reservedQuantity || 0) - reservation.quantity);
                    newItem.reservations = newItem.reservations.filter(r => r.id !== checklistToCheckout.id);
                }
            }

            // B. Debita do estoque físico a quantidade realmente utilizada
            const usedItem = checkoutForm.itemsUsed.find(u => u.itemId === item.id);
            if (usedItem && usedItem.quantity > 0) {
                newItem.quantity = Math.max(0, newItem.quantity - usedItem.quantity);

                // C. Gera histórico de movimentação
                movements.unshift({
                    id: `mov_${Date.now()}_${item.id}`,
                    itemId: item.id,
                    type: 'saida',
                    quantity: usedItem.quantity,
                    date: checkoutForm.date,
                    observation: `Obra: ${checklistToCheckout.project}`
                });
            }

            return newItem;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));
        localStorage.setItem('stock_movements', JSON.stringify(movements));

        alert("Check-Out finalizado com sucesso!");
        setChecklistToCheckout(null);
    };

    // --- RENDERIZAÇÃO ---

    if (view === 'checkin') {
        return (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg max-w-4xl mx-auto">
                <div className="mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <CheckCircleIcon className="w-8 h-8 text-green-600" />
                        Novo Check-In (Saída para Obra)
                    </h2>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Obra / Cliente</label>
                        <input 
                            type="text" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={newCheckIn.project}
                            onChange={e => setNewCheckIn({...newCheckIn, project: e.target.value})}
                            placeholder="Nome da Obra"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Técnico Responsável</label>
                        <input 
                            type="text" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={newCheckIn.technician}
                            onChange={e => setNewCheckIn({...newCheckIn, technician: e.target.value})}
                            placeholder="Nome do Técnico"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Data de Saída</label>
                        <input 
                            type="date" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={newCheckIn.date}
                            onChange={e => setNewCheckIn({...newCheckIn, date: e.target.value})}
                        />
                    </div>
                </div>

                <div className="bg-gray-50 dark:bg-gray-700/30 p-4 rounded-lg border border-gray-200 dark:border-gray-600 mb-6">
                    <h3 className="font-bold text-gray-800 dark:text-white mb-3">Adicionar Materiais</h3>
                    <div className="flex gap-2">
                        <select 
                            className="flex-1 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2"
                            value={selectedItemToAdd}
                            onChange={e => setSelectedItemToAdd(e.target.value)}
                        >
                            <option value="">Selecione o material...</option>
                            {stockItems.map(item => (
                                <option key={item.id} value={item.id}>
                                    {item.name} (Disp: {item.quantity - (item.reservedQuantity || 0)})
                                </option>
                            ))}
                        </select>
                        <input 
                            type="number" 
                            min="1" 
                            className="w-24 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2"
                            value={quantityToAdd}
                            onChange={e => setQuantityToAdd(Number(e.target.value))}
                        />
                        <button 
                            onClick={addItemToCheckIn}
                            className="bg-indigo-600 text-white px-4 rounded-md hover:bg-indigo-700"
                        >
                            <PlusIcon className="w-5 h-5" />
                        </button>
                    </div>
                </div>

                {newCheckIn.items.length > 0 && (
                    <div className="mb-6 border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
                        <table className="min-w-full text-sm text-left">
                            <thead className="bg-gray-100 dark:bg-gray-700">
                                <tr>
                                    <th className="px-4 py-2">Item</th>
                                    <th className="px-4 py-2 text-center">Qtd</th>
                                    <th className="px-4 py-2 w-10"></th>
                                </tr>
                            </thead>
                            <tbody>
                                {newCheckIn.items.map((item, idx) => (
                                    <tr key={idx} className="border-b dark:border-gray-700 last:border-0">
                                        <td className="px-4 py-2">{item.name}</td>
                                        <td className="px-4 py-2 text-center font-bold">{item.quantity}</td>
                                        <td className="px-4 py-2 text-center">
                                            <button 
                                                onClick={() => removeItemFromCheckIn(idx)}
                                                className="text-red-500 hover:text-red-700"
                                            >
                                                <TrashIcon className="w-4 h-4" />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                <div className="flex justify-end">
                    <button 
                        onClick={saveCheckIn}
                        className="flex items-center gap-2 bg-green-600 text-white px-6 py-2 rounded-md hover:bg-green-700 font-medium"
                    >
                        <SaveIcon className="w-5 h-5" />
                        Confirmar Check-In
                    </button>
                </div>
            </div>
        );
    }

    if (view === 'checkout') {
        const activeChecklists = checklists.filter(c => c.status === 'open');

        if (checklistToCheckout) {
            return (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg max-w-4xl mx-auto">
                    <div className="flex justify-between items-center mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white">
                            Finalizando Obra: {checklistToCheckout.project}
                        </h2>
                        <button 
                            onClick={() => setChecklistToCheckout(null)}
                            className="text-gray-500 hover:text-gray-700 underline text-sm"
                        >
                            Cancelar
                        </button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Técnico (Retorno)</label>
                            <input 
                                type="text" 
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                                value={checkoutForm.technician}
                                onChange={e => setCheckoutForm({...checkoutForm, technician: e.target.value})}
                                placeholder="Quem devolveu?"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Data de Retorno</label>
                            <input 
                                type="date" 
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                                value={checkoutForm.date}
                                onChange={e => setCheckoutForm({...checkoutForm, date: e.target.value})}
                            />
                        </div>
                    </div>

                    <div className="bg-yellow-50 dark:bg-yellow-900/10 border border-yellow-200 dark:border-yellow-800 rounded-lg p-4 mb-6">
                        <h3 className="font-bold text-yellow-800 dark:text-yellow-200 mb-3 flex items-center gap-2">
                            <CubeIcon className="w-5 h-5" /> Conferência de Materiais
                        </h3>
                        <div className="overflow-hidden bg-white dark:bg-gray-800 rounded border border-gray-200 dark:border-gray-700">
                            <table className="min-w-full text-sm">
                                <thead className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300">
                                    <tr>
                                        <th className="px-4 py-2 text-left">Item</th>
                                        <th className="px-4 py-2 text-center">Levado</th>
                                        <th className="px-4 py-2 text-center w-32">Utilizado</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {checkoutForm.itemsUsed.map((item, idx) => (
                                        <tr key={idx} className="border-b dark:border-gray-700 last:border-0">
                                            <td className="px-4 py-2 font-medium">{item.name}</td>
                                            <td className="px-4 py-2 text-center text-gray-500">
                                                {checklistToCheckout.itemsReserved[idx].quantity}
                                            </td>
                                            <td className="px-4 py-2">
                                                <input 
                                                    type="number"
                                                    min="0"
                                                    className="w-full text-center border-gray-300 dark:border-gray-600 rounded p-1"
                                                    value={item.quantity}
                                                    onChange={e => updateUsedQuantity(idx, Number(e.target.value))}
                                                />
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <p className="text-xs text-yellow-700 dark:text-yellow-400 mt-2">
                            * Informe a quantidade que foi realmente gasta na obra. A diferença retornará ao estoque disponível.
                        </p>
                    </div>

                    <div className="flex justify-end">
                        <button 
                            onClick={saveCheckout}
                            className="bg-indigo-600 text-white px-6 py-2 rounded-md hover:bg-indigo-700 font-medium"
                        >
                            Finalizar Obra
                        </button>
                    </div>
                </div>
            );
        }

        return (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                <div className="mb-6">
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <ClipboardListIcon className="w-8 h-8 text-indigo-600" />
                        Check-Out (Obras em Andamento)
                    </h2>
                    <p className="text-gray-500 mt-1">Selecione uma obra para realizar a devolução e baixa de materiais.</p>
                </div>

                {activeChecklists.length === 0 ? (
                    <div className="text-center py-12 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-lg text-gray-500">
                        Nenhuma obra em aberto no momento.
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {activeChecklists.map(checklist => (
                            <div 
                                key={checklist.id}
                                onClick={() => startCheckout(checklist)}
                                className="border border-gray-200 dark:border-gray-700 p-4 rounded-lg cursor-pointer hover:border-indigo-500 hover:shadow-md transition-all bg-gray-50 dark:bg-gray-700/30"
                            >
                                <h3 className="font-bold text-lg text-gray-900 dark:text-white mb-2">{checklist.project}</h3>
                                <div className="text-sm text-gray-500 dark:text-gray-400 space-y-1">
                                    <p>Técnico: {checklist.technicianCheckIn}</p>
                                    <p>Saída: {new Date(checklist.dateCheckIn).toLocaleDateString('pt-BR')}</p>
                                    <p className="font-medium text-indigo-600 dark:text-indigo-400 mt-2">
                                        {checklist.itemsReserved.length} itens reservados
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        );
    }

    return null;
};

