    status: 'open' | 'closed';
    itemsReserved: { itemId: string; quantity: number; name: string }[];

    // Checkout data
    dateCheckOut?: string;
    technicianCheckOut?: string;
    itemsUsed?: { itemId: string; quantity: number; name: string }[];
}

const CheckListPage: React.FC<CheckListPageProps> = ({ view }) => {
    // --- ESTADOS ---
    const [checklists, setChecklists] = useState<CheckListEntry[]>([]);
    const [stockItems, setStockItems] = useState<StockItem[]>([]);

    // Estado Check-In
    const [project, setProject] = useState('');
    const [technicianIn, setTechnicianIn] = useState('');
    const [dateIn, setDateIn] = useState(new Date().toISOString().split('T')[0]);
    const [itemsIn, setItemsIn] = useState<{ itemId: string; quantity: number; name: string }[]>([]);

    // Auxiliar Check-In
    const [selectedItemId, setSelectedItemId] = useState('');
