    // Estado Check-Out
    const [checklistToClose, setChecklistToClose] = useState<CheckListEntry | null>(null);
    const [technicianOut, setTechnicianOut] = useState('');
    const [dateOut, setDateOut] = useState(new Date().toISOString().split('T')[0]);
    const [itemsUsed, setItemsUsed] = useState<{ itemId: string; quantity: number; name: string }[]>([]);

    // --- CARREGAMENTO INICIAL ---
    useEffect(() => {
        const loadData = () => {
            try {
                const savedChecklists = localStorage.getItem('checklist_entries');
                const savedStock = localStorage.getItem('stock_items');

                if (savedChecklists) setChecklists(JSON.parse(savedChecklists));
                if (savedStock) setStockItems(JSON.parse(savedStock));
            } catch (e) {
                console.error("Erro ao carregar dados:", e);
            }
        };
        loadData();
    }, []);

    // --- SALVAMENTO AUTOMÁTICO ---
    useEffect(() => {
        if (checklists.length > 0) { // Evita salvar array vazio se o load falhar momentaneamente
            localStorage.setItem('checklist_entries', JSON.stringify(checklists));
        }
    }, [checklists]);

    // --- FUNÇÕES: CHECK-IN ---
    const handleAddItem = () => {
        if (!selectedItemId || selectedQty <= 0) return;

        const stockItem = stockItems.find(i => i.id === selectedItemId);
        if (!stockItem) return;

        // Validar se tem estoque disponível (Qtd Total - Reservados)
        const available = stockItem.quantity - (stockItem.reservedQuantity || 0);
        if (selectedQty > available) {
            alert(`Estoque insuficiente! Disponível: ${available} ${stockItem.unit}`);
            return;
        }

        const existing = itemsIn.find(i => i.itemId === selectedItemId);
        if (existing) {
            alert("Este item já está na lista. Remova-o para adicionar novamente com outra quantidade.");
            return;
        }

        setItemsIn([...itemsIn, { itemId: stockItem.id, quantity: selectedQty, name: stockItem.name }]);
        setSelectedItemId('');
        setSelectedQty(1);
    };

    const handleRemoveItem = (index: number) => {
        const newItems = [...itemsIn];
        newItems.splice(index, 1);
        setItemsIn(newItems);
    };

    const handleSaveCheckIn = () => {
        if (!project || !technicianIn || itemsIn.length === 0) {
            alert("Preencha a Obra, Técnico e adicione pelo menos um item.");
            return;
        }

        const newEntry: CheckListEntry = {
            id: Date.now().toString(),
            project,
            technicianCheckIn: technicianIn,
            dateCheckIn: dateIn,
            status: 'open',
            itemsReserved: itemsIn
        };

        // Atualizar Estoque (Reservar)
        const updatedStock = stockItems.map(item => {
            const reservedItem = itemsIn.find(i => i.itemId === item.id);
            if (reservedItem) {
                return {
                    ...item,
                    reservedQuantity: (item.reservedQuantity || 0) + reservedItem.quantity,
                    reservations: [
                        ...(item.reservations || []),
                        {
                            id: newEntry.id,
                            sourceName: project,
                            quantity: reservedItem.quantity,
                            date: dateIn
                        }
                    ]
                };
            }
            return item;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));

        setChecklists([newEntry, ...checklists]);

        // Reset
        setProject('');
        setTechnicianIn('');
        setItemsIn([]);
        alert("Check-In realizado com sucesso!");
    };

    // --- FUNÇÕES: CHECK-OUT ---
    const handleSelectChecklist = (entry: CheckListEntry) => {
        setChecklistToClose(entry);
        setTechnicianOut('');
        setDateOut(new Date().toISOString().split('T')[0]);
        // Copia os itens reservados como base para os usados
        setItemsUsed(entry.itemsReserved.map(i => ({...i})));
    };

    const handleUsedChange = (idx: number, val: number) => {
        const newItems = [...itemsUsed];
        newItems[idx].quantity = val;
        setItemsUsed(newItems);
    };

    const handleSaveCheckOut = () => {
        if (!checklistToClose || !technicianOut) {
            alert("Informe o técnico responsável pelo retorno.");
            return;
        }

        // 1. Atualizar Checklist
        const updatedChecklists = checklists.map(c => 
            c.id === checklistToClose.id 
            ? { ...c, status: 'closed' as const, dateCheckOut: dateOut, technicianCheckOut: technicianOut, itemsUsed }
            : c
        );
        setChecklists(updatedChecklists);

        // 2. Atualizar Estoque (Baixa Real + Remover Reserva)
        const movements: StockMovement[] = JSON.parse(localStorage.getItem('stock_movements') || '[]');

        const updatedStock = stockItems.map(item => {
            let newItem = { ...item };

            // A. Remover Reserva
            if (newItem.reservations) {
                const reservation = newItem.reservations.find(r => r.id === checklistToClose.id);
                if (reservation) {
                    newItem.reservedQuantity = Math.max(0, (newItem.reservedQuantity || 0) - reservation.quantity);
                    newItem.reservations = newItem.reservations.filter(r => r.id !== checklistToClose.id);
                }
            }

            // B. Debitar Consumo Real
            const used = itemsUsed.find(u => u.itemId === item.id);
            if (used && used.quantity > 0) {
                newItem.quantity = Math.max(0, newItem.quantity - used.quantity);

                // Gerar movimento
                movements.unshift({
                    id: `mov_out_${Date.now()}_${item.id}`,
                    itemId: item.id,
                    type: 'saida',
                    quantity: used.quantity,
                    date: dateOut,
                    observation: `Obra: ${checklistToClose.project}`
                });
            }

            return newItem;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));
        localStorage.setItem('stock_movements', JSON.stringify(movements));

        setChecklistToClose(null);
        alert("Check-Out finalizado com sucesso!");
    };

    // --- RENDER: CHECK-IN ---
    if (view === 'checkin') {
        return (
            <div className="max-w-4xl mx-auto space-y-6">
                <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border-l-4 border-green-500">
                    <div className="flex items-center gap-4 mb-6">
                        <div className="p-3 bg-green-100 dark:bg-green-900 rounded-full">
                            <CheckCircleIcon className="w-8 h-8 text-green-600 dark:text-green-400" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Check-In de Obra</h2>
                            <p className="text-gray-500 dark:text-gray-400">Registre a saída de materiais para uma nova obra ou cliente.</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                        <div className="md:col-span-1">
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Data</label>
                            <input 
                                type="date" 
                                value={dateIn} 
                                onChange={e => setDateIn(e.target.value)}
                                className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-gray-900 dark:text-white"
                            />
                        </div>
                        <div className="md:col-span-1">
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Cliente / Obra</label>
                            <input 
                                type="text" 
                                value={project} 
                                onChange={e => setProject(e.target.value)}
                                className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-gray-900 dark:text-white"
                                placeholder="Identificação da Obra"
                            />
                        </div>
                        <div className="md:col-span-1">
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Técnico Responsável</label>
                            <input 
                                type="text" 
                                value={technicianIn} 
                                onChange={e => setTechnicianIn(e.target.value)}
                                className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-gray-900 dark:text-white"
                                placeholder="Quem retirou?"
                            />
                        </div>
                    </div>

                    <div className="border-t border-gray-200 dark:border-gray-700 pt-6">
                        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
                            <CubeIcon className="w-5 h-5" />
                            Seleção de Materiais
                        </h3>

                        <div className="flex flex-col sm:flex-row gap-3 mb-4 bg-gray-50 dark:bg-gray-700/50 p-4 rounded-lg">
                            <select 
                                value={selectedItemId} 
                                onChange={e => setSelectedItemId(e.target.value)}
                                className="flex-1 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2"
                            >
                                <option value="">Selecione um item...</option>
                                {stockItems.map(item => {
                                    const available = item.quantity - (item.reservedQuantity || 0);
                                    return (
                                        <option key={item.id} value={item.id} disabled={available <= 0}>
                                            {item.name} (Disp: {available} {item.unit})
                                        </option>
                                    );
                                })}
                            </select>
                            <input 
                                type="number" 
                                min="1" 
                                value={selectedQty}
                                onChange={e => setSelectedQty(Number(e.target.value))}
                                className="w-24 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2"
                            />
                            <button 
                                onClick={handleAddItem}
                                className="bg-green-600 text-white px-4 py-2 rounded-md hover:bg-green-700 transition-colors flex items-center justify-center gap-1"
                            >
                                <PlusIcon className="w-5 h-5" /> Adicionar
                            </button>
                        </div>

                        {itemsIn.length > 0 ? (
                            <div className="overflow-hidden border border-gray-200 dark:border-gray-700 rounded-lg">
                                <table className="min-w-full text-left text-sm">
                                    <thead className="bg-gray-100 dark:bg-gray-700">
                                        <tr>
                                            <th className="px-4 py-2 font-medium text-gray-700 dark:text-gray-300">Item</th>
                                            <th className="px-4 py-2 font-medium text-gray-700 dark:text-gray-300 text-center">Qtd. Reservada</th>
                                            <th className="px-4 py-2 font-medium text-gray-700 dark:text-gray-300 text-right">Ação</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700 bg-white dark:bg-gray-800">
                                        {itemsIn.map((item, idx) => (
                                            <tr key={idx}>
                                                <td className="px-4 py-2 text-gray-900 dark:text-white">{item.name}</td>
                                                <td className="px-4 py-2 text-center text-gray-900 dark:text-white font-bold">{item.quantity}</td>
                                                <td className="px-4 py-2 text-right">
                                                    <button onClick={() => handleRemoveItem(idx)} className="text-red-500 hover:text-red-700">
                                                        <TrashIcon className="w-4 h-4" />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        ) : (
                            <div className="text-center py-8 text-gray-500 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg">
                                Nenhum item adicionado à lista.
                            </div>
                        )}
                    </div>

                    <div className="mt-8 flex justify-end">
                        <button 
                            onClick={handleSaveCheckIn}
                            className="bg-indigo-600 text-white px-8 py-3 rounded-md hover:bg-indigo-700 font-bold shadow-lg transition-all transform hover:scale-105 flex items-center gap-2"
                        >
                            <SaveIcon className="w-5 h-5" />
                            Confirmar Saída (Check-In)
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    // --- RENDER: CHECK-OUT ---
    if (view === 'checkout') {
        const activeList = checklists.filter(c => c.status === 'open');

        // MODO FORMULÁRIO DE FECHAMENTO
        if (checklistToClose) {
            return (
                <div className="max-w-4xl mx-auto space-y-6">
                    <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border-l-4 border-indigo-500">
                        <div className="flex justify-between items-center border-b border-gray-200 dark:border-gray-700 pb-4 mb-6">
                            <div>
                                <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Finalizar Obra</h2>
                                <p className="text-indigo-600 dark:text-indigo-400 font-medium">{checklistToClose.project}</p>
                            </div>
                            <button 
                                onClick={() => setChecklistToClose(null)}
                                className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 underline"
                            >
                                Cancelar
                            </button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Data Retorno</label>
                                <input 
                                    type="date" 
                                    value={dateOut} 
                                    onChange={e => setDateOut(e.target.value)}
                                    className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-gray-900 dark:text-white"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Técnico (Devolução)</label>
                                <input 
                                    type="text" 
                                    value={technicianOut} 
                                    onChange={e => setTechnicianOut(e.target.value)}
                                    className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-gray-900 dark:text-white"
                                    placeholder="Quem devolveu?"
                                />
                            </div>
                        </div>

                        <div className="bg-yellow-50 dark:bg-yellow-900/10 p-4 rounded-lg border border-yellow-200 dark:border-yellow-800 mb-6">
                            <h3 className="font-bold text-yellow-800 dark:text-yellow-200 mb-3 flex items-center gap-2">
                                <ClipboardListIcon className="w-5 h-5" /> Conferência de Retorno
                            </h3>
                            <div className="bg-white dark:bg-gray-800 rounded-lg overflow-hidden border border-gray-200 dark:border-gray-700 shadow-sm">
                                <table className="min-w-full text-sm">
                                    <thead className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300">
                                        <tr>
                                            <th className="px-4 py-2 text-left">Material</th>
                                            <th className="px-4 py-2 text-center">Qtd. Levada</th>
                                            <th className="px-4 py-2 text-center bg-indigo-50 dark:bg-indigo-900/20 w-32 border-l border-r border-indigo-100 dark:border-indigo-800">Qtd. Utilizada</th>
                                            <th className="px-4 py-2 text-center text-gray-500">Retorno ao Estoque</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                        {itemsUsed.map((item, idx) => {
                                            const levado = checklistToClose.itemsReserved[idx].quantity;
                                            const retorno = levado - item.quantity;
                                            return (
                                                <tr key={idx}>
                                                    <td className="px-4 py-2 font-medium text-gray-900 dark:text-white">{item.name}</td>
                                                    <td className="px-4 py-2 text-center text-gray-600 dark:text-gray-400">{levado}</td>
                                                    <td className="px-4 py-2 bg-indigo-50 dark:bg-indigo-900/20 border-l border-r border-indigo-100 dark:border-indigo-800">
                                                        <input 
                                                            type="number" 
                                                            min="0"
                                                            max={levado}
                                                            value={item.quantity}
                                                            onChange={e => handleUsedChange(idx, Number(e.target.value))}
                                                            className="w-full text-center rounded border-gray-300 dark:border-gray-600 p-1 font-bold text-indigo-700 dark:text-indigo-300"
                                                        />
                                                    </td>
                                                    <td className="px-4 py-2 text-center font-medium text-green-600 dark:text-green-400">
                                                        {retorno > 0 ? `+${retorno}` : '-'}
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                            <p className="text-xs text-yellow-700 dark:text-yellow-400 mt-2 text-center">
                                * Indique quanto foi <strong>gasto</strong> na obra. O restante voltará para o estoque disponível.
                            </p>
                        </div>

                        <div className="flex justify-end gap-3">
                            <button 
                                onClick={handleSaveCheckOut}
                                className="bg-indigo-600 text-white px-6 py-2 rounded-md hover:bg-indigo-700 font-bold shadow transition-colors"
                            >
                                Finalizar Check-Out
                            </button>
                        </div>
                    </div>
                </div>
            );
        }

        // MODO LISTA DE OBRAS ABERTAS
        return (
            <div className="space-y-6">
                <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border-l-4 border-indigo-500">
                    <div className="flex items-center gap-4 mb-2">
                        <div className="p-3 bg-indigo-100 dark:bg-indigo-900 rounded-full">
                            <ClipboardListIcon className="w-8 h-8 text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Check-Out (Retorno)</h2>
                            <p className="text-gray-500 dark:text-gray-400">Selecione uma obra em andamento para realizar a baixa dos materiais.</p>
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {activeList.length > 0 ? activeList.map(entry => (
                        <div 
                            key={entry.id} 
                            onClick={() => handleSelectChecklist(entry)}
                            className="bg-white dark:bg-gray-800 p-5 rounded-lg shadow border border-gray-200 dark:border-gray-700 hover:border-indigo-500 cursor-pointer transition-all hover:shadow-md group"
                        >
                            <div className="flex justify-between items-start mb-3">
                                <h3 className="text-lg font-bold text-gray-900 dark:text-white group-hover:text-indigo-600">{entry.project}</h3>
                                <span className="bg-yellow-100 text-yellow-800 text-xs px-2 py-1 rounded-full font-semibold">Em Aberto</span>
                            </div>
                            <div className="text-sm text-gray-500 dark:text-gray-400 space-y-1">
                                <p><span className="font-medium">Técnico:</span> {entry.technicianCheckIn}</p>
                                <p><span className="font-medium">Saída:</span> {new Date(entry.dateCheckIn).toLocaleDateString('pt-BR')}</p>
                                <p className="pt-2 text-indigo-600 dark:text-indigo-400 font-medium">
                                    {entry.itemsReserved.length} itens reservados
                                </p>
                            </div>
                        </div>
                    )) : (
                        <div className="col-span-full py-12 text-center border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-xl">
                            <CubeIcon className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                            <p className="text-gray-500 dark:text-gray-400 text-lg">Nenhuma obra em aberto no momento.</p>
                            <p className="text-sm text-gray-400">Realize um Check-In para iniciar uma obra.</p>
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return null;
};

export default CheckListPage;

import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ClipboardListIcon, SaveIcon, TrashIcon, PlusIcon } from '../assets/icons';
import type { CheckListPageProps, StockItem, StockMovement } from '../types';

interface CheckListEntry {
    id: string;
    project: string;
    technicianCheckIn: string;
    dateCheckIn: string;
    status: 'open' | 'closed';
    itemsReserved: { itemId: string; quantity: number; name: string }[];

    // Checkout data
    dateCheckOut?: string;
    technicianCheckOut?: string;
    itemsUsed?: { itemId: string; quantity: number; name: string }[];
}

const CheckListPage: React.FC<CheckListPageProps> = ({ view }) => {
    // Dados globais
    const [checklists, setChecklists] = useState<CheckListEntry[]>([]);
    const [stockItems, setStockItems] = useState<StockItem[]>([]);

    // Estado Check-In
    const [newCheckIn, setNewCheckIn] = useState<Partial<CheckListEntry>>({
        project: '',
        technicianCheckIn: '',
        dateCheckIn: new Date().toISOString().split('T')[0],
        itemsReserved: []
    });

    // Estado temporário para adição de itens
    const [selectedItem, setSelectedItem] = useState('');
    const [selectedQty, setSelectedQty] = useState(1);

    // Estado Check-Out
    const [selectedChecklist, setSelectedChecklist] = useState<CheckListEntry | null>(null);
    const [checkoutData, setCheckoutData] = useState<{
        technicianCheckOut: string;
        dateCheckOut: string;
        itemsUsed: { itemId: string; quantity: number; name: string }[];
    }>({
        technicianCheckOut: '',
        dateCheckOut: new Date().toISOString().split('T')[0],
        itemsUsed: []
    });

    // Carregar dados
    useEffect(() => {
        const savedChecklists = localStorage.getItem('checklist_entries');
        const savedStock = localStorage.getItem('stock_items');

        if (savedChecklists) setChecklists(JSON.parse(savedChecklists));
        if (savedStock) setStockItems(JSON.parse(savedStock));
    }, []);

    // Salvar dados
    useEffect(() => {
        if (checklists.length > 0 || localStorage.getItem('checklist_entries')) {
            localStorage.setItem('checklist_entries', JSON.stringify(checklists));
        }
    }, [checklists]);

    // --- LÓGICA CHECK-IN ---

    const handleAddItem = () => {
        if (!selectedItem || selectedQty <= 0) return;

        const stockItem = stockItems.find(i => i.id === selectedItem);
        if (!stockItem) return;

        // Verifica se já existe na lista
        const exists = newCheckIn.itemsReserved?.find(i => i.itemId === selectedItem);
        if (exists) {
            alert('Item já adicionado. Remova-o para alterar a quantidade.');
            return;
        }

        const newItem = {
            itemId: stockItem.id,
            quantity: selectedQty,
            name: stockItem.name
        };

        setNewCheckIn(prev => ({
            ...prev,
            itemsReserved: [...(prev.itemsReserved || []), newItem]
        }));

        setSelectedItem('');
        setSelectedQty(1);
    };

    const handleRemoveItem = (index: number) => {
        setNewCheckIn(prev => ({
            ...prev,
            itemsReserved: prev.itemsReserved?.filter((_, i) => i !== index)
        }));
    };

    const handleSaveCheckIn = () => {
        if (!newCheckIn.project || !newCheckIn.technicianCheckIn || !newCheckIn.itemsReserved?.length) {
            alert('Preencha todos os campos e adicione itens.');
            return;
        }

        const entry: CheckListEntry = {
            id: Date.now().toString(),
            project: newCheckIn.project,
            technicianCheckIn: newCheckIn.technicianCheckIn,
            dateCheckIn: newCheckIn.dateCheckIn || new Date().toISOString().split('T')[0],
            status: 'open',
            itemsReserved: newCheckIn.itemsReserved
        };

        // Atualiza Estoque (Reserva)
        const updatedStock = stockItems.map(item => {
            const reserved = entry.itemsReserved.find(i => i.itemId === item.id);
            if (reserved) {
                return {
                    ...item,
                    reservedQuantity: (item.reservedQuantity || 0) + reserved.quantity,
                    reservations: [...(item.reservations || []), {
                        id: entry.id,
                        sourceName: entry.project,
                        quantity: reserved.quantity,
                        date: entry.dateCheckIn
                    }]
                };
            }
            return item;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));
        setChecklists(prev => [entry, ...prev]);

        // Reset
        setNewCheckIn({
            project: '',
            technicianCheckIn: '',
            dateCheckIn: new Date().toISOString().split('T')[0],
            itemsReserved: []
        });

        alert('Check-In realizado com sucesso!');
    };

    // --- LÓGICA CHECK-OUT ---

    const handleSelectCheckout = (checklist: CheckListEntry) => {
        setSelectedChecklist(checklist);
        setCheckoutData({
            technicianCheckOut: '',
            dateCheckOut: new Date().toISOString().split('T')[0],
            itemsUsed: checklist.itemsReserved.map(i => ({...i})) // Inicia sugerindo que usou tudo
        });
    };

    const handleUsedQtyChange = (index: number, qty: number) => {
        const newItems = [...checkoutData.itemsUsed];
        newItems[index].quantity = qty;
        setCheckoutData(prev => ({ ...prev, itemsUsed: newItems }));
    };

    const handleSaveCheckout = () => {
        if (!selectedChecklist || !checkoutData.technicianCheckOut) {
            alert('Informe o técnico responsável.');
            return;
        }

        // 1. Atualiza Checklist
        const updatedChecklists = checklists.map(c => 
            c.id === selectedChecklist.id 
            ? { 
                ...c, 
                status: 'closed' as const,
                dateCheckOut: checkoutData.dateCheckOut,
                technicianCheckOut: checkoutData.technicianCheckOut,
                itemsUsed: checkoutData.itemsUsed
              }
            : c
        );
        setChecklists(updatedChecklists);

        // 2. Movimentação e Baixa de Estoque
        const movements: StockMovement[] = JSON.parse(localStorage.getItem('stock_movements') || '[]');

        const updatedStock = stockItems.map(item => {
            let newItem = { ...item };

            // Remove a reserva
            if (newItem.reservations) {
                const res = newItem.reservations.find(r => r.id === selectedChecklist.id);
                if (res) {
                    newItem.reservedQuantity = Math.max(0, (newItem.reservedQuantity || 0) - res.quantity);
                    newItem.reservations = newItem.reservations.filter(r => r.id !== selectedChecklist.id);
                }
            }

            // Consome o estoque real baseado no uso
            const used = checkoutData.itemsUsed.find(u => u.itemId === item.id);
            if (used && used.quantity > 0) {
                newItem.quantity = Math.max(0, newItem.quantity - used.quantity);

                movements.unshift({
                    id: `mov_out_${Date.now()}_${item.id}`,
                    itemId: item.id,
                    type: 'saida',
                    quantity: used.quantity,
                    date: checkoutData.dateCheckOut,
                    observation: `Check-Out: ${selectedChecklist.project}`
                });
            }

            return newItem;
        });

        setStockItems(updatedStock);
        localStorage.setItem('stock_items', JSON.stringify(updatedStock));
        localStorage.setItem('stock_movements', JSON.stringify(movements));

        setSelectedChecklist(null);
        alert('Check-Out finalizado!');
    };

    // --- RENDER ---

    if (view === 'checkin') {
        return (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                <div className="flex items-center gap-2 mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                    <CheckCircleIcon className="w-6 h-6 text-green-600" />
                    <h2 className="text-xl font-bold text-gray-900 dark:text-white">Check-In (Saída para Obra)</h2>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Cliente / Obra</label>
                        <input 
                            type="text" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={newCheckIn.project}
                            onChange={e => setNewCheckIn({...newCheckIn, project: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Técnico Responsável</label>
                        <input 
                            type="text" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={newCheckIn.technicianCheckIn}
                            onChange={e => setNewCheckIn({...newCheckIn, technicianCheckIn: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Data</label>
                        <input 
                            type="date" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={newCheckIn.dateCheckIn}
                            onChange={e => setNewCheckIn({...newCheckIn, dateCheckIn: e.target.value})}
                        />
                    </div>
                </div>

                <div className="bg-gray-50 dark:bg-gray-700/50 p-4 rounded-lg mb-6">
                    <h3 className="text-sm font-bold text-gray-700 dark:text-gray-300 mb-3">Adicionar Materiais</h3>
                    <div className="flex gap-2">
                        <select 
                            className="flex-1 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2"
                            value={selectedItem}
                            onChange={e => setSelectedItem(e.target.value)}
                        >
                            <option value="">Selecione...</option>
                            {stockItems.map(i => (
                                <option key={i.id} value={i.id}>{i.name} (Disp: {i.quantity - (i.reservedQuantity || 0)})</option>
                            ))}
                        </select>
                        <input 
                            type="number" 
                            min="1"
                            className="w-24 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2"
                            value={selectedQty}
                            onChange={e => setSelectedQty(Number(e.target.value))}
                        />
                        <button 
                            onClick={handleAddItem}
                            className="px-4 bg-indigo-600 text-white rounded-md hover:bg-indigo-700"
                        >
                            <PlusIcon className="w-5 h-5" />
                        </button>
                    </div>
                </div>

                {newCheckIn.itemsReserved && newCheckIn.itemsReserved.length > 0 && (
                    <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden mb-6">
                        <table className="min-w-full text-sm text-left">
                            <thead className="bg-gray-100 dark:bg-gray-700">
                                <tr>
                                    <th className="px-4 py-2">Item</th>
                                    <th className="px-4 py-2 text-center">Qtd</th>
                                    <th className="px-4 py-2 w-10"></th>
                                </tr>
                            </thead>
                            <tbody>
                                {newCheckIn.itemsReserved.map((item, idx) => (
                                    <tr key={idx} className="border-b dark:border-gray-700 last:border-0">
                                        <td className="px-4 py-2">{item.name}</td>
                                        <td className="px-4 py-2 text-center font-bold">{item.quantity}</td>
                                        <td className="px-4 py-2 text-center">
                                            <button onClick={() => handleRemoveItem(idx)} className="text-red-500 hover:text-red-700">
                                                <TrashIcon className="w-4 h-4" />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                <div className="flex justify-end">
                    <button 
                        onClick={handleSaveCheckIn}
                        className="flex items-center gap-2 px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium"
                    >
                        <SaveIcon className="w-5 h-5" />
                        Salvar Check-In
                    </button>
                </div>
            </div>
        );
    }

    if (view === 'checkout') {
        const activeChecklists = checklists.filter(c => c.status === 'open');

        if (selectedChecklist) {
            return (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                    <div className="flex justify-between items-center mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white">Finalizar: {selectedChecklist.project}</h2>
                        <button onClick={() => setSelectedChecklist(null)} className="text-gray-500 hover:text-gray-700 underline">Cancelar</button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Técnico (Retorno)</label>
                            <input 
                                type="text" 
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                                value={checkoutData.technicianCheckOut}
                                onChange={e => setCheckoutData({...checkoutData, technicianCheckOut: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Data Retorno</label>
                            <input 
                                type="date" 
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                                value={checkoutData.dateCheckOut}
                                onChange={e => setCheckoutData({...checkoutData, dateCheckOut: e.target.value})}
                            />
                        </div>
                    </div>

                    <div className="mb-6">
                        <h3 className="font-bold text-gray-800 dark:text-white mb-2">Conferência de Materiais</h3>
                        <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
                            <table className="min-w-full text-sm">
                                <thead className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300">
                                    <tr>
                                        <th className="px-4 py-2 text-left">Item</th>
                                        <th className="px-4 py-2 text-center">Levado</th>
                                        <th className="px-4 py-2 text-center">Utilizado (Gasto)</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {checkoutData.itemsUsed.map((item, idx) => (
                                        <tr key={idx} className="border-b dark:border-gray-700 last:border-0">
                                            <td className="px-4 py-2 font-medium">{item.name}</td>
                                            <td className="px-4 py-2 text-center text-gray-500">{selectedChecklist.itemsReserved[idx].quantity}</td>
                                            <td className="px-4 py-2 text-center">
                                                <input 
                                                    type="number"
                                                    min="0"
                                                    value={item.quantity}
                                                    onChange={e => handleUsedQtyChange(idx, Number(e.target.value))}
                                                    className="w-24 text-center border border-gray-300 dark:border-gray-600 rounded p-1"
                                                />
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <p className="text-xs text-gray-500 mt-2">* Informe a quantidade que foi realmente gasta. O restante volta ao estoque.</p>
                    </div>

                    <div className="flex justify-end">
                        <button 
                            onClick={handleSaveCheckout}
                            className="bg-indigo-600 text-white px-6 py-2 rounded-md hover:bg-indigo-700 font-medium"
                        >
                            Finalizar Obra
                        </button>
                    </div>
                </div>
            );
        }

        return (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                <div className="flex items-center gap-2 mb-6">
                    <ClipboardListIcon className="w-6 h-6 text-indigo-600" />
                    <h2 className="text-xl font-bold text-gray-900 dark:text-white">Check-Out (Obras em Andamento)</h2>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {activeChecklists.length > 0 ? activeChecklists.map(checklist => (
                        <div 
                            key={checklist.id}
                            onClick={() => handleSelectCheckout(checklist)}
                            className="border border-gray-200 dark:border-gray-700 p-4 rounded-lg cursor-pointer hover:border-indigo-500 hover:shadow-md transition-all bg-gray-50 dark:bg-gray-700/30"
                        >
                            <h3 className="font-bold text-lg text-gray-900 dark:text-white">{checklist.project}</h3>
                            <div className="text-sm text-gray-500 dark:text-gray-400 mt-2">
                                <p>Técnico: {checklist.technicianCheckIn}</p>
                                <p>Data: {new Date(checklist.dateCheckIn).toLocaleDateString('pt-BR')}</p>
                                <p className="mt-1 font-medium text-indigo-600">{checklist.itemsReserved.length} itens</p>
                            </div>
                        </div>
                    )) : (
                        <div className="col-span-full py-10 text-center text-gray-500 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-lg">
                            Nenhuma obra em aberto.
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return null;
};

export default CheckListPage;

import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ClipboardListIcon, SaveIcon, TrashIcon, PlusIcon, CubeIcon, ArrowUpIcon, ArrowDownIcon } from '../assets/icons';
import type { CheckListPageProps, StockItem, StockMovement } from '../types';

interface CheckListEntry {
    id: string;
    project: string;
    technicianCheckIn: string;
    dateCheckIn: string;
    status: 'open' | 'closed';
    items: { itemId: string; quantity: number; name: string }[];

    // Checkout data
    dateCheckOut?: string;
    technicianCheckOut?: string;
    itemsReturned?: { itemId: string; quantity: number; name: string }[];
}

const CheckListPage: React.FC<CheckListPageProps> = ({ view }) => {
    const [checklists, setChecklists] = useState<CheckListEntry[]>([]);
    const [stockItems, setStockItems] = useState<StockItem[]>([]);

    // State Check-In
    const [checkInForm, setCheckInForm] = useState({
        project: '',
        technician: '',
        date: new Date().toISOString().split('T')[0]
    });
    const [checkInItems, setCheckInItems] = useState<{ itemId: string; quantity: number; name: string }[]>([]);

    // Aux Check-In
    const [selectedItem, setSelectedItem] = useState('');
    const [selectedQty, setSelectedQty] = useState(1);

    // State Check-Out
    const [selectedChecklist, setSelectedChecklist] = useState<CheckListEntry | null>(null);
    const [checkOutForm, setCheckOutForm] = useState({
        technician: '',
        date: new Date().toISOString().split('T')[0]
    });
    // Store returned quantities mapping: itemId -> quantity returned
    const [returnedQuantities, setReturnedQuantities] = useState<Record<string, number>>({});

    // Load Data
    useEffect(() => {
        const savedChecklists = localStorage.getItem('checklist_entries');
        const savedStock = localStorage.getItem('stock_items');

        if (savedChecklists) setChecklists(JSON.parse(savedChecklists));
        if (savedStock) setStockItems(JSON.parse(savedStock));
    }, []);

    // Save Data Handler
    const saveToLocalStorage = (newChecklists: CheckListEntry[], newStock: StockItem[], movements: StockMovement[]) => {
        localStorage.setItem('checklist_entries', JSON.stringify(newChecklists));
        localStorage.setItem('stock_items', JSON.stringify(newStock));

        const existingMovements = JSON.parse(localStorage.getItem('stock_movements') || '[]');
        localStorage.setItem('stock_movements', JSON.stringify([...movements, ...existingMovements]));

        setChecklists(newChecklists);
        setStockItems(newStock);
    };

    // --- CHECK-IN LOGIC ---

    const addCheckInItem = () => {
        if (!selectedItem || selectedQty <= 0) return;
        const item = stockItems.find(i => i.id === selectedItem);
        if (!item) return;

        if (item.quantity < selectedQty) {
            alert(`Estoque insuficiente. Disponível: ${item.quantity} ${item.unit}`);
            return;
        }

        const exists = checkInItems.find(i => i.itemId === selectedItem);
        if (exists) {
            alert('Item já adicionado à lista.');
            return;
        }

        setCheckInItems([...checkInItems, { itemId: item.id, quantity: selectedQty, name: item.name }]);
        setSelectedItem('');
        setSelectedQty(1);
    };

    const removeCheckInItem = (index: number) => {
        const newItems = [...checkInItems];
        newItems.splice(index, 1);
        setCheckInItems(newItems);
    };

    const confirmCheckIn = () => {
        if (!checkInForm.project || !checkInForm.technician || checkInItems.length === 0) {
            alert('Preencha todos os dados e adicione itens.');
            return;
        }

        const newEntry: CheckListEntry = {
            id: Date.now().toString(),
            project: checkInForm.project,
            technicianCheckIn: checkInForm.technician,
            dateCheckIn: checkInForm.date,
            status: 'open',
            items: checkInItems
        };

        // Update Stock (Decrement) & Create Movements
        const newMovements: StockMovement[] = [];
        const updatedStock = stockItems.map(item => {
            const entryItem = checkInItems.find(i => i.itemId === item.id);
            if (entryItem) {
                newMovements.push({
                    id: `mov_${Date.now()}_${item.id}`,
                    itemId: item.id,
                    type: 'saida',
                    quantity: entryItem.quantity,
                    date: checkInForm.date,
                    observation: `Check-In Obra: ${checkInForm.project}`
                });
                return { ...item, quantity: item.quantity - entryItem.quantity };
            }
            return item;
        });

        saveToLocalStorage([newEntry, ...checklists], updatedStock, newMovements);

        // Reset
        setCheckInForm({ project: '', technician: '', date: new Date().toISOString().split('T')[0] });
        setCheckInItems([]);
        alert('Check-In realizado com sucesso! Itens descontados do estoque.');
    };

    // --- CHECK-OUT LOGIC ---

    const startCheckOut = (checklist: CheckListEntry) => {
        setSelectedChecklist(checklist);
        setCheckOutForm({ technician: '', date: new Date().toISOString().split('T')[0] });
        // Initialize returns with 0
        const initialReturns: Record<string, number> = {};
        checklist.items.forEach(i => initialReturns[i.itemId] = 0);
        setReturnedQuantities(initialReturns);
    };

    const confirmCheckOut = () => {
        if (!selectedChecklist || !checkOutForm.technician) {
            alert('Preencha o técnico responsável.');
            return;
        }

        const itemsReturnedList = selectedChecklist.items.map(item => ({
            itemId: item.itemId,
            name: item.name,
            quantity: returnedQuantities[item.itemId] || 0
        }));

        // Update Entry
        const updatedChecklists = checklists.map(c => 
            c.id === selectedChecklist.id 
            ? { 
                ...c, 
                status: 'closed' as const, 
                dateCheckOut: checkOutForm.date, 
                technicianCheckOut: checkOutForm.technician,
                itemsReturned: itemsReturnedList
              }
            : c
        );

        // Update Stock (Increment Returned) & Create Movements
        const newMovements: StockMovement[] = [];
        const updatedStock = stockItems.map(item => {
            const returnedQty = returnedQuantities[item.id];
            if (returnedQty && returnedQty > 0) {
                newMovements.push({
                    id: `mov_ret_${Date.now()}_${item.id}`,
                    itemId: item.id,
                    type: 'entrada',
                    quantity: returnedQty,
                    date: checkOutForm.date,
                    observation: `Retorno Obra: ${selectedChecklist.project}`
                });
                return { ...item, quantity: item.quantity + returnedQty };
            }
            return item;
        });

        saveToLocalStorage(updatedChecklists, updatedStock, newMovements);

        setSelectedChecklist(null);
        alert('Check-Out finalizado! Sobras retornaram ao estoque.');
    };

    // --- RENDER ---

    if (view === 'checkin') {
        return (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                <div className="flex items-center gap-3 mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                    <div className="p-2 bg-green-100 dark:bg-green-900 rounded-lg">
                        <ArrowUpIcon className="w-6 h-6 text-green-600 dark:text-green-400" />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white">Novo Check-In (Saída)</h2>
                        <p className="text-sm text-gray-500">Registre a retirada de materiais para uma obra.</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Obra / Cliente</label>
                        <input 
                            type="text" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={checkInForm.project}
                            onChange={e => setCheckInForm({...checkInForm, project: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Técnico Responsável</label>
                        <input 
                            type="text" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={checkInForm.technician}
                            onChange={e => setCheckInForm({...checkInForm, technician: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Data Saída</label>
                        <input 
                            type="date" 
                            className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                            value={checkInForm.date}
                            onChange={e => setCheckInForm({...checkInForm, date: e.target.value})}
                        />
                    </div>
                </div>

                <div className="bg-gray-50 dark:bg-gray-700/30 p-4 rounded-lg mb-6 border border-gray-200 dark:border-gray-600">
                    <h3 className="font-bold text-sm text-gray-800 dark:text-white mb-2 flex items-center gap-2">
                        <CubeIcon className="w-4 h-4" /> Adicionar Itens
                    </h3>
                    <div className="flex gap-2">
                        <select 
                            className="flex-1 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2"
                            value={selectedItem}
                            onChange={e => setSelectedItem(e.target.value)}
                        >
                            <option value="">Selecione o material...</option>
                            {stockItems.map(item => (
                                <option key={item.id} value={item.id} disabled={item.quantity <= 0}>
                                    {item.name} (Disp: {item.quantity} {item.unit})
                                </option>
                            ))}
                        </select>
                        <input 
                            type="number" 
                            min="1"
                            className="w-24 rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2"
                            value={selectedQty}
                            onChange={e => setSelectedQty(Number(e.target.value))}
                        />
                        <button onClick={addCheckInItem} className="bg-green-600 text-white px-4 rounded-md hover:bg-green-700">
                            <PlusIcon className="w-5 h-5" />
                        </button>
                    </div>
                </div>

                {checkInItems.length > 0 && (
                    <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden mb-6">
                        <table className="min-w-full text-sm text-left">
                            <thead className="bg-gray-100 dark:bg-gray-700">
                                <tr>
                                    <th className="px-4 py-2">Item</th>
                                    <th className="px-4 py-2 text-center">Qtd. Saída</th>
                                    <th className="px-4 py-2 w-10"></th>
                                </tr>
                            </thead>
                            <tbody>
                                {checkInItems.map((item, idx) => (
                                    <tr key={idx} className="border-b dark:border-gray-700 last:border-0 bg-white dark:bg-gray-800">
                                        <td className="px-4 py-2 font-medium">{item.name}</td>
                                        <td className="px-4 py-2 text-center text-red-600 dark:text-red-400 font-bold">-{item.quantity}</td>
                                        <td className="px-4 py-2">
                                            <button onClick={() => removeCheckInItem(idx)} className="text-gray-400 hover:text-red-500">
                                                <TrashIcon className="w-4 h-4" />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                <div className="flex justify-end">
                    <button 
                        onClick={confirmCheckIn}
                        className="flex items-center gap-2 bg-green-600 text-white px-6 py-2 rounded-md hover:bg-green-700 font-bold shadow-sm"
                    >
                        <SaveIcon className="w-5 h-5" />
                        Confirmar Saída
                    </button>
                </div>
            </div>
        );
    }

    if (view === 'checkout') {
        const activeChecklists = checklists.filter(c => c.status === 'open');

        if (selectedChecklist) {
            return (
                <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                    <div className="flex justify-between items-center mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                        <div>
                            <h2 className="text-xl font-bold text-gray-900 dark:text-white">Conferência de Retorno</h2>
                            <p className="text-indigo-600 dark:text-indigo-400 font-medium">{selectedChecklist.project}</p>
                        </div>
                        <button onClick={() => setSelectedChecklist(null)} className="text-sm text-gray-500 hover:text-gray-700 underline">Cancelar</button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Técnico (Retorno)</label>
                            <input 
                                type="text" 
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                                value={checkOutForm.technician}
                                onChange={e => setCheckOutForm({...checkOutForm, technician: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Data Retorno</label>
                            <input 
                                type="date" 
                                className="mt-1 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2"
                                value={checkOutForm.date}
                                onChange={e => setCheckOutForm({...checkOutForm, date: e.target.value})}
                            />
                        </div>
                    </div>

                    <div className="mb-6 border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
                        <table className="min-w-full text-sm">
                            <thead className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300">
                                <tr>
                                    <th className="px-4 py-2 text-left">Item</th>
                                    <th className="px-4 py-2 text-center text-red-600 dark:text-red-400">Qtd. Saída</th>
                                    <th className="px-4 py-2 text-center text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/10 w-32 border-x border-green-100 dark:border-green-900">Qtd. Retorno</th>
                                    <th className="px-4 py-2 text-center">Utilizado</th>
                                </tr>
                            </thead>
                            <tbody>
                                {selectedChecklist.items.map((item, idx) => {
                                    const returned = returnedQuantities[item.itemId] || 0;
                                    const used = item.quantity - returned;
                                    return (
                                        <tr key={idx} className="border-b dark:border-gray-700 last:border-0">
                                            <td className="px-4 py-2 font-medium">{item.name}</td>
                                            <td className="px-4 py-2 text-center font-bold text-gray-600">{item.quantity}</td>
                                            <td className="px-4 py-2 text-center bg-green-50 dark:bg-green-900/10 border-x border-green-100 dark:border-green-900">
                                                <input 
                                                    type="number"
                                                    min="0"
                                                    max={item.quantity}
                                                    className="w-full text-center bg-white dark:bg-gray-700 border border-green-300 dark:border-green-700 rounded p-1 font-bold text-green-700 dark:text-green-400"
                                                    value={returned}
                                                    onChange={e => setReturnedQuantities({...returnedQuantities, [item.itemId]: Number(e.target.value)})}
                                                />
                                            </td>
                                            <td className="px-4 py-2 text-center text-gray-500">
                                                {used}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                        <div className="bg-gray-50 dark:bg-gray-700/50 p-2 text-xs text-center text-gray-500">
                            * Itens retornados serão somados de volta ao estoque.
                        </div>
                    </div>

                    <div className="flex justify-end">
                        <button 
                            onClick={confirmCheckOut}
                            className="bg-indigo-600 text-white px-6 py-2 rounded-md hover:bg-indigo-700 font-bold shadow-sm"
                        >
                            Finalizar e Baixar
                        </button>
                    </div>
                </div>
            );
        }

        return (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                <div className="flex items-center gap-3 mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                    <div className="p-2 bg-indigo-100 dark:bg-indigo-900 rounded-lg">
                        <ArrowDownIcon className="w-6 h-6 text-indigo-600 dark:text-indigo-400" />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white">Check-Out (Retorno)</h2>
                        <p className="text-sm text-gray-500">Selecione uma obra para dar baixa e retornar sobras.</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    {activeChecklists.length > 0 ? activeChecklists.map(c => (
                        <div 
                            key={c.id} 
                            onClick={() => startCheckOut(c)}
                            className="border border-gray-200 dark:border-gray-700 p-4 rounded-lg hover:border-indigo-500 cursor-pointer bg-gray-50 dark:bg-gray-700/30 transition-all shadow-sm hover:shadow-md group"
                        >
                            <h3 className="font-bold text-gray-900 dark:text-white group-hover:text-indigo-600">{c.project}</h3>
                            <div className="text-xs text-gray-500 dark:text-gray-400 mt-2 space-y-1">
                                <p>Técnico: {c.technicianCheckIn}</p>
                                <p>Saída: {new Date(c.dateCheckIn).toLocaleDateString('pt-BR')}</p>
                                <p className="font-medium text-gray-700 dark:text-gray-300 mt-2">{c.items.length} itens listados</p>
                            </div>
                        </div>
                    )) : (
                        <div className="col-span-full py-12 text-center text-gray-400 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-lg">
                            Nenhuma obra pendente de retorno.
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return null;
};

export default CheckListPage;

import React, { useState, useEffect } from 'react';
import { ClipboardCheckIcon, SaveIcon, CheckCircleIcon, PhotographIcon, TrashIcon, CalendarIcon, UsersIcon } from '../assets/icons';
import type { CheckListPageProps } from '../types';

// Definição dos tipos locais para o formulário
interface ChecklistItem {
    id: string;
    label: string;
    checked: boolean;
}

interface ServiceRecord {
    id: string;
    type: 'CHECKIN' | 'CHECKOUT';
    client: string;
    technician: string;
    date: string;
    items: ChecklistItem[];
    observations: string;
}

const QUESTIONS_CHECKIN = [
    "Uso de EPIs completos pela equipe",
    "Isolamento da área de trabalho",
    "Conferência visual dos materiais entregues",
    "Vistoria prévia do telhado (telhas quebradas?)",
    "Vistoria do padrão de entrada de energia",
    "Fotos iniciais do local tiradas"
];

const QUESTIONS_CHECKOUT = [
    "Módulos fixados e alinhados",
    "Estrutura aterrada corretamente",
    "Conectores MC4 crimpados e travados",
    "Organização do cabeamento (DC e AC)",
    "Inversor fixado, ligado e configurado (Wi-Fi)",
    "Testes de tensão e funcionamento realizados",
    "Limpeza completa do local da obra",
    "Explicação básica de funcionamento ao cliente",
    "Fotos finais do serviço enviadas"
];

const CheckListPage: React.FC<CheckListPageProps> = ({ view }) => {
    // Histórico de formulários salvos
    const [history, setHistory] = useState<ServiceRecord[]>([]);

    // Estado do Formulário Atual
    const [client, setClient] = useState('');
    const [technician, setTechnician] = useState('');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [observations, setObservations] = useState('');

    // Estado dos Checkboxes (Dinâmico base na view)
    const [checks, setChecks] = useState<ChecklistItem[]>([]);

    // Carregar histórico e configurar perguntas iniciais
    useEffect(() => {
        const savedHistory = localStorage.getItem('service_checklists');
        if (savedHistory) setHistory(JSON.parse(savedHistory));

        // Inicializar perguntas baseadas na view
        const questions = view === 'checkin' ? QUESTIONS_CHECKIN : QUESTIONS_CHECKOUT;
        setChecks(questions.map((q, index) => ({
            id: index.toString(),
            label: q,
            checked: false
        })));

        // Limpar campos ao trocar de tela
        setClient('');
        setTechnician('');
        setObservations('');
    }, [view]);

    const handleCheckToggle = (id: string) => {
        setChecks(prev => prev.map(item => 
            item.id === id ? { ...item, checked: !item.checked } : item
        ));
    };

    const handleSave = () => {
        if (!client || !technician) {
            alert("Por favor, preencha o Cliente e o Técnico Responsável.");
            return;
        }

        const newRecord: ServiceRecord = {
            id: Date.now().toString(),
            type: view === 'checkin' ? 'CHECKIN' : 'CHECKOUT',
            client,
            technician,
            date,
            items: checks,
            observations
        };

        const updatedHistory = [newRecord, ...history];
        setHistory(updatedHistory);
        localStorage.setItem('service_checklists', JSON.stringify(updatedHistory));

        alert("Formulário salvo com sucesso!");

        // Resetar form mantendo a view
        setClient('');
        setTechnician('');
        setObservations('');
        setChecks(checks.map(c => ({ ...c, checked: false })));
    };

    const handleDelete = (id: string) => {
        if (window.confirm("Deseja excluir este registro?")) {
            const updated = history.filter(h => h.id !== id);
            setHistory(updated);
            localStorage.setItem('service_checklists', JSON.stringify(updated));
        }
    };

    // Calcular progresso
    const completedCount = checks.filter(c => c.checked).length;
    const progress = Math.round((completedCount / checks.length) * 100);

    // Filtrar histórico para exibir na tela atual
    const currentTypeHistory = history.filter(h => h.type === (view === 'checkin' ? 'CHECKIN' : 'CHECKOUT'));

    return (
        <div className="max-w-5xl mx-auto space-y-8">

            {/* FORMULÁRIO PRINCIPAL */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
                <div className={`p-6 border-b-4 ${view === 'checkin' ? 'border-green-500' : 'border-indigo-500'}`}>
                    <div className="flex items-center gap-3">
                        <div className={`p-3 rounded-full ${view === 'checkin' ? 'bg-green-100 text-green-600' : 'bg-indigo-100 text-indigo-600'}`}>
                            <ClipboardCheckIcon className="w-8 h-8" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
                                {view === 'checkin' ? 'Check-In de Instalação (Início)' : 'Check-Out de Instalação (Finalização)'}
                            </h2>
                            <p className="text-gray-500 dark:text-gray-400">
                                {view === 'checkin' 
                                    ? 'Formulário de vistoria inicial e preparação do local.' 
                                    : 'Formulário de validação final e entrega técnica.'}
                            </p>
                        </div>
                    </div>
                </div>

                <div className="p-6 space-y-6">
                    {/* Dados Gerais */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Cliente / Obra</label>
                            <div className="relative">
                                <span className="absolute left-3 top-2.5 text-gray-400"><UsersIcon className="w-5 h-5"/></span>
                                <input 
                                    type="text" 
                                    value={client}
                                    onChange={e => setClient(e.target.value)}
                                    className="pl-10 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2.5 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                                    placeholder="Nome do Cliente"
                                />
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Técnico Responsável</label>
                            <input 
                                type="text" 
                                value={technician}
                                onChange={e => setTechnician(e.target.value)}
                                className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2.5 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                                placeholder="Nome do Técnico"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Data</label>
                            <div className="relative">
                                <span className="absolute left-3 top-2.5 text-gray-400"><CalendarIcon className="w-5 h-5"/></span>
                                <input 
                                    type="date" 
                                    value={date}
                                    onChange={e => setDate(e.target.value)}
                                    className="pl-10 w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2.5 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                                />
                            </div>
                        </div>
                    </div>

                    <hr className="border-gray-200 dark:border-gray-700" />

                    {/* Lista de Verificação */}
                    <div>
                        <div className="flex justify-between items-end mb-4">
                            <h3 className="text-lg font-bold text-gray-900 dark:text-white">Itens de Verificação</h3>
                            <span className={`text-sm font-bold ${progress === 100 ? 'text-green-600' : 'text-gray-500'}`}>
                                {completedCount} de {checks.length} completados ({progress}%)
                            </span>
                        </div>

                        {/* Barra de Progresso */}
                        <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2.5 mb-6">
                            <div 
                                className={`h-2.5 rounded-full transition-all duration-500 ${view === 'checkin' ? 'bg-green-600' : 'bg-indigo-600'}`} 
                                style={{ width: `${progress}%` }}
                            ></div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {checks.map((item) => (
                                <label 
                                    key={item.id} 
                                    className={`flex items-start p-4 border rounded-lg cursor-pointer transition-all ${
                                        item.checked 
                                        ? 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800' 
                                        : 'bg-white dark:bg-gray-700 border-gray-200 dark:border-gray-600 hover:border-gray-300'
                                    }`}
                                >
                                    <input 
                                        type="checkbox" 
                                        checked={item.checked} 
                                        onChange={() => handleCheckToggle(item.id)}
                                        className={`mt-1 w-5 h-5 rounded border-gray-300 focus:ring-offset-0 ${view === 'checkin' ? 'text-green-600 focus:ring-green-500' : 'text-indigo-600 focus:ring-indigo-500'}`}
                                    />
                                    <span className={`ml-3 text-sm ${item.checked ? 'text-gray-900 dark:text-white font-medium' : 'text-gray-600 dark:text-gray-300'}`}>
                                        {item.label}
                                    </span>
                                </label>
                            ))}
                        </div>
                    </div>

                    {/* Observações */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Observações Adicionais</label>
                        <textarea 
                            rows={3}
                            value={observations}
                            onChange={e => setObservations(e.target.value)}
                            className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-3 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                            placeholder="Descreva detalhes importantes, problemas encontrados ou notas para a equipe..."
                        />
                    </div>

                    {/* Botão Salvar */}
                    <div className="flex justify-end pt-4">
                        <button 
                            onClick={handleSave}
                            className={`flex items-center gap-2 px-8 py-3 text-white rounded-lg font-bold shadow-lg transform transition hover:scale-105 ${
                                view === 'checkin' 
                                ? 'bg-green-600 hover:bg-green-700' 
                                : 'bg-indigo-600 hover:bg-indigo-700'
                            }`}
                        >
                            <SaveIcon className="w-5 h-5" />
                            Salvar {view === 'checkin' ? 'Check-In' : 'Check-Out'}
                        </button>
                    </div>
                </div>
            </div>

            {/* HISTÓRICO RECENTE */}
            <div className="space-y-4">
                <h3 className="text-xl font-bold text-gray-800 dark:text-white px-2">Histórico Recente ({view === 'checkin' ? 'Check-Ins' : 'Check-Outs'})</h3>

                {currentTypeHistory.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {currentTypeHistory.map(record => (
                            <div key={record.id} className="bg-white dark:bg-gray-800 p-5 rounded-lg shadow border border-gray-100 dark:border-gray-700 hover:shadow-md transition-shadow relative group">
                                <button 
                                    onClick={() => handleDelete(record.id)}
                                    className="absolute top-4 right-4 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                >
                                    <TrashIcon className="w-5 h-5" />
                                </button>

                                <div className="flex justify-between items-start mb-2">
                                    <h4 className="font-bold text-lg text-gray-900 dark:text-white">{record.client}</h4>
                                    <span className="text-xs text-gray-500 bg-gray-100 dark:bg-gray-700 px-2 py-1 rounded">
                                        {new Date(record.date).toLocaleDateString('pt-BR')}
                                    </span>
                                </div>

                                <p className="text-sm text-gray-600 dark:text-gray-300 mb-3">Técnico: <span className="font-medium">{record.technician}</span></p>

                                <div className="space-y-1 mb-3">
                                    <p className="text-xs font-semibold text-gray-500 uppercase">Itens Verificados:</p>
                                    <div className="flex flex-wrap gap-2">
                                        {record.items.filter(i => i.checked).slice(0, 3).map((i, idx) => (
                                            <span key={idx} className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-50 text-green-700 dark:bg-green-900/30 dark:text-green-300 border border-green-100 dark:border-green-800">
                                                <CheckCircleIcon className="w-3 h-3 mr-1" />
                                                {i.label.substring(0, 20)}...
                                            </span>
                                        ))}
                                        {record.items.filter(i => i.checked).length > 3 && (
                                            <span className="text-xs text-gray-400 self-center">+{record.items.filter(i => i.checked).length - 3} itens</span>
                                        )}
                                    </div>
                                </div>

                                {record.observations && (
                                    <div className="bg-gray-50 dark:bg-gray-700/50 p-3 rounded text-sm text-gray-600 dark:text-gray-300 italic">
                                        "{record.observations}"
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center py-10 bg-gray-50 dark:bg-gray-800 rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-700">
                        <ClipboardCheckIcon className="w-12 h-12 text-gray-300 mx-auto mb-2" />
                        <p className="text-gray-500 dark:text-gray-400">Nenhum registro encontrado.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default CheckListPage;
